    defer gin_array_index.deinit(alloc);
    const array_indexed_schema = try applyDdlPlanToRuntimeSchemaAlloc(alloc, json_indexed_schema, gin_array_index);
    defer runtime_schema.freeSchema(alloc, array_indexed_schema);
    const tags = relationalColumnForField(array_indexed_schema, "tags", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(tags.indexed);
    try std.testing.expectEqual(runtime_schema.RelationalIndexLifecycle.building, tags.index_lifecycle);
    try std.testing.expect(tags.index_generation != 0);
    try std.testing.expect(tags.index_name != null);
    try std.testing.expectEqualStrings("users_tags_gin", tags.index_name.?);

    var invalid_gin_scalar = try lowerDdlPlanAlloc(
        alloc,
        "CREATE INDEX users_status_gin ON users USING gin (status);",
    );
    defer invalid_gin_scalar.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, upper_unique_schema, invalid_gin_scalar));

    var invalid_gin_json_opclass = try lowerDdlPlanAlloc(
        alloc,
        "CREATE INDEX users_metadata_bad_gin ON users USING gin (metadata array_ops);",
    );
    defer invalid_gin_json_opclass.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, upper_unique_schema, invalid_gin_json_opclass));

    var invalid_gin_array_opclass = try lowerDdlPlanAlloc(
        alloc,
        "CREATE INDEX users_tags_bad_gin ON users USING gin (tags jsonb_path_ops);",
    );
    defer invalid_gin_array_opclass.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, upper_unique_schema, invalid_gin_array_opclass));

    var drop_ordinary_index = try lowerDdlPlanAlloc(alloc, "DROP INDEX users_status_active_idx;");
    defer drop_ordinary_index.deinit(alloc);
    const ordinary_dropped = try applyDdlPlanToRuntimeSchemaAlloc(alloc, upper_unique_schema, drop_ordinary_index);
    defer runtime_schema.freeSchema(alloc, ordinary_dropped);
    const dropped_status = relationalColumnForField(ordinary_dropped, "status", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!dropped_status.indexed);
    try std.testing.expectEqual(runtime_schema.RelationalIndexLifecycle.ready, dropped_status.index_lifecycle);
    try std.testing.expectEqual(@as(u64, 0), dropped_status.index_generation);
    try std.testing.expect(dropped_status.index_name == null);
    try std.testing.expectEqual(@as(usize, 0), dropped_status.index_where.len);

    var concurrent_status_index = try lowerDdlPlanAlloc(
        alloc,
        "CREATE INDEX users_status_concurrent_idx ON users (status);",
    );
    defer concurrent_status_index.deinit(alloc);
    const concurrent_indexed = try applyDdlPlanToRuntimeSchemaAlloc(alloc, ordinary_dropped, concurrent_status_index);
    defer runtime_schema.freeSchema(alloc, concurrent_indexed);
    var drop_concurrent_index = try lowerDdlPlanAlloc(alloc, "DROP INDEX CONCURRENTLY users_status_concurrent_idx;");
    defer drop_concurrent_index.deinit(alloc);
    const concurrent_dropped = try applyDdlPlanToRuntimeSchemaAlloc(alloc, concurrent_indexed, drop_concurrent_index);
    defer runtime_schema.freeSchema(alloc, concurrent_dropped);
    const concurrent_dropped_status = relationalColumnForField(concurrent_dropped, "status", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!concurrent_dropped_status.indexed);
    try std.testing.expect(concurrent_dropped_status.index_name == null);

    var drop_generated_index = try lowerDdlPlanAlloc(alloc, "DROP INDEX users_lower_email_idx;");
    defer drop_generated_index.deinit(alloc);
    const generated_dropped = try applyDdlPlanToRuntimeSchemaAlloc(alloc, unique_schema, drop_generated_index);
    defer runtime_schema.freeSchema(alloc, generated_dropped);
    try std.testing.expect(relationalColumnForField(generated_dropped, "users_lower_email_idx", null) == null);

    var drop_unique_index = try lowerDdlPlanAlloc(alloc, "DROP INDEX users_tenant_lower_email_key;");
    defer drop_unique_index.deinit(alloc);
    const unique_dropped = try applyDdlPlanToRuntimeSchemaAlloc(alloc, unique_schema, drop_unique_index);
    defer runtime_schema.freeSchema(alloc, unique_dropped);
    try std.testing.expectEqual(@as(usize, 0), unique_dropped.unique_constraints.len);

    var drop_missing_index = try lowerDdlPlanAlloc(alloc, "DROP INDEX missing_idx;");
    defer drop_missing_index.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, unique_schema, drop_missing_index));

    var drop_missing_if_exists = try lowerDdlPlanAlloc(alloc, "DROP INDEX IF EXISTS missing_idx;");
    defer drop_missing_if_exists.deinit(alloc);
    const unchanged_drop = try applyDdlPlanToRuntimeSchemaAlloc(alloc, unique_schema, drop_missing_if_exists);
    defer runtime_schema.freeSchema(alloc, unchanged_drop);
    try std.testing.expectEqual(@as(usize, unique_schema.relational_columns.len), unchanged_drop.relational_columns.len);
    try std.testing.expectEqual(@as(usize, unique_schema.unique_constraints.len), unchanged_drop.unique_constraints.len);

    const empty_drop_noop = try applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, drop_missing_if_exists);
    defer runtime_schema.freeSchema(alloc, empty_drop_noop);
    try std.testing.expectEqual(runtime_schema.StorageMode.document, empty_drop_noop.storage_mode);
    try std.testing.expectEqual(@as(usize, 0), empty_drop_noop.relational_columns.len);

    var multi_column_index = try lowerDdlPlanAlloc(alloc, "CREATE INDEX users_tenant_status_idx ON users (tenant_id, status);");
    defer multi_column_index.deinit(alloc);
    const multi_indexed = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, multi_column_index);
    defer runtime_schema.freeSchema(alloc, multi_indexed);
    const indexed_tenant = relationalColumnForField(multi_indexed, "tenant_id", null) orelse return error.TestUnexpectedResult;
    const indexed_status = relationalColumnForField(multi_indexed, "status", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(indexed_tenant.indexed);
    try std.testing.expect(indexed_status.indexed);
    try std.testing.expectEqual(runtime_schema.RelationalIndexLifecycle.building, indexed_tenant.index_lifecycle);
    try std.testing.expectEqual(runtime_schema.RelationalIndexLifecycle.building, indexed_status.index_lifecycle);
    try std.testing.expectEqual(indexed_tenant.index_generation, indexed_status.index_generation);
    try std.testing.expect(indexed_tenant.index_generation != 0);
    try std.testing.expect(indexed_tenant.index_name != null);
    try std.testing.expect(indexed_status.index_name != null);
    try std.testing.expectEqualStrings("users_tenant_status_idx", indexed_tenant.index_name.?);
    try std.testing.expectEqualStrings("users_tenant_status_idx", indexed_status.index_name.?);

    var drop_multi_column_index = try lowerDdlPlanAlloc(alloc, "DROP INDEX users_tenant_status_idx;");
    defer drop_multi_column_index.deinit(alloc);
    const multi_dropped = try applyDdlPlanToRuntimeSchemaAlloc(alloc, multi_indexed, drop_multi_column_index);
    defer runtime_schema.freeSchema(alloc, multi_dropped);
    const dropped_tenant = relationalColumnForField(multi_dropped, "tenant_id", null) orelse return error.TestUnexpectedResult;
    const dropped_multi_status = relationalColumnForField(multi_dropped, "status", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(!dropped_tenant.indexed);
    try std.testing.expect(!dropped_multi_status.indexed);
    try std.testing.expect(dropped_tenant.index_name == null);
    try std.testing.expect(dropped_multi_status.index_name == null);
}

test "postgres sql adapter applies updated-at trigger ddl plan to runtime schema" {
    const alloc = std.testing.allocator;
    var create = try lowerDdlPlanAlloc(
        alloc,
        "CREATE TABLE usage_records (id uuid PRIMARY KEY, updated_at_ns bigint, CONSTRAINT usage_records_updated_check CHECK (updated_at_ns >= 0));",
    );
    defer create.deinit(alloc);
    const schema = try applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, create);
    defer runtime_schema.freeSchema(alloc, schema);

    var table_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON TABLE usage_records IS 'metered usage rows';");
    defer table_comment.deinit(alloc);
    const table_commented = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, table_comment);
    defer runtime_schema.freeSchema(alloc, table_commented);
    try std.testing.expectEqual(runtime_schema.StorageMode.relational, table_commented.storage_mode);
    try std.testing.expectEqual(schema.relational_columns.len, table_commented.relational_columns.len);

    var column_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON COLUMN usage_records.updated_at_ns IS 'update clock';");
    defer column_comment.deinit(alloc);
    const column_commented = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, column_comment);
    defer runtime_schema.freeSchema(alloc, column_commented);
    try std.testing.expect(relationalColumnForField(column_commented, "updated_at_ns", null) != null);

    var clear_column_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON COLUMN usage_records.updated_at_ns IS NULL;");
    defer clear_column_comment.deinit(alloc);
    const column_cleared = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, clear_column_comment);
    defer runtime_schema.freeSchema(alloc, column_cleared);
    try std.testing.expect(relationalColumnForField(column_cleared, "updated_at_ns", null) != null);

    var missing_column_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON COLUMN usage_records.missing IS 'missing';");
    defer missing_column_comment.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, missing_column_comment));

    var index_plan = try lowerDdlPlanAlloc(alloc, "CREATE INDEX usage_records_updated_idx ON usage_records (updated_at_ns);");
    defer index_plan.deinit(alloc);
    const indexed = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, index_plan);
    defer runtime_schema.freeSchema(alloc, indexed);

    var index_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON INDEX usage_records_updated_idx IS 'updated-at lookup';");
    defer index_comment.deinit(alloc);
    const index_commented = try applyDdlPlanToRuntimeSchemaAlloc(alloc, indexed, index_comment);
    defer runtime_schema.freeSchema(alloc, index_commented);
    try std.testing.expect(relationalIndexNameExists(index_commented, "usage_records_updated_idx"));

    var constraint_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON CONSTRAINT usage_records_updated_check ON usage_records IS 'valid update clock';");
    defer constraint_comment.deinit(alloc);
    const constraint_commented = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, constraint_comment);
    defer runtime_schema.freeSchema(alloc, constraint_commented);
    try std.testing.expect(relationalConstraintNameExists(constraint_commented, "usage_records", "usage_records_updated_check"));

    var missing_constraint_comment = try lowerDdlPlanAlloc(alloc, "COMMENT ON CONSTRAINT missing_check ON usage_records IS 'missing';");
    defer missing_constraint_comment.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, missing_constraint_comment));

    var trigger = try lowerDdlPlanAlloc(
        alloc,
        "CREATE TRIGGER update_timestamp BEFORE UPDATE ON usage_records EXECUTE FUNCTION touch_updated_at('updated_at_ns');",
    );
    defer trigger.deinit(alloc);
    const updated = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, trigger);
    defer runtime_schema.freeSchema(alloc, updated);

    const column = relationalColumnForField(updated, "updated_at_ns", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(column.on_update_value != null);
    try std.testing.expectEqual(runtime_schema.RelationalDefaultKind.now_ns, column.on_update_value.?.kind);

    var drop_trigger = try lowerDdlPlanAlloc(
        alloc,
        "DROP TRIGGER update_timestamp ON usage_records;",
    );
    defer drop_trigger.deinit(alloc);
    const dropped = try applyDdlPlanToRuntimeSchemaAlloc(alloc, updated, drop_trigger);
    defer runtime_schema.freeSchema(alloc, dropped);
    const dropped_column = relationalColumnForField(dropped, "updated_at_ns", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(dropped_column.on_update_value == null);

    var drop_trigger_if_exists = try lowerDdlPlanAlloc(
        alloc,
        "DROP TRIGGER IF EXISTS update_timestamp ON usage_records;",
    );
    defer drop_trigger_if_exists.deinit(alloc);
    const unchanged = try applyDdlPlanToRuntimeSchemaAlloc(alloc, dropped, drop_trigger_if_exists);
    defer runtime_schema.freeSchema(alloc, unchanged);
    const unchanged_column = relationalColumnForField(unchanged, "updated_at_ns", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(unchanged_column.on_update_value == null);

    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, dropped, drop_trigger));

    var drop_table = try lowerDdlPlanAlloc(alloc, "DROP TABLE usage_records;");
    defer drop_table.deinit(alloc);
    const dropped_table = try applyDdlPlanToRuntimeSchemaAlloc(alloc, schema, drop_table);
    defer runtime_schema.freeSchema(alloc, dropped_table);
    try std.testing.expectEqual(runtime_schema.StorageMode.document, dropped_table.storage_mode);
    try std.testing.expectEqual(@as(usize, 0), dropped_table.relational_columns.len);
    try std.testing.expect(dropped_table.primary_key == null);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, drop_table));

    var drop_table_if_exists = try lowerDdlPlanAlloc(alloc, "DROP TABLE IF EXISTS usage_records;");
    defer drop_table_if_exists.deinit(alloc);
    const missing_table_noop = try applyDdlPlanToRuntimeSchemaAlloc(alloc, .{}, drop_table_if_exists);
    defer runtime_schema.freeSchema(alloc, missing_table_noop);
    try std.testing.expectEqual(runtime_schema.StorageMode.document, missing_table_noop.storage_mode);
}

test "postgres sql adapter compiles create table ddl plan to public schema json" {
    const alloc = std.testing.allocator;
    var create = try lowerDdlPlanAlloc(
        alloc,
        \\CREATE TABLE users (
        \\  id uuid DEFAULT gen_random_uuid() PRIMARY KEY,
        \\  tenant_id text NOT NULL,
        \\  email text COLLATE "C",
        \\  attrs jsonb,
        \\  tags text[],
        \\  updated_at_ns bigint DEFAULT 0,
        \\  current_day_ns date DEFAULT CURRENT_DATE,
        \\  CONSTRAINT users_tenant_email_key UNIQUE (tenant_id, email),
        \\  CONSTRAINT users_updated_check CHECK (updated_at_ns >= 0)
        \\);
        ,
    );
    defer create.deinit(alloc);

    var applied = try applyDdlPlanToSchemaJsonAlloc(alloc, "", create);
    defer applied.deinit(alloc);
    try std.testing.expect(!applied.requires_rebuild);
    try std.testing.expect(!applied.validation_required);
    try std.testing.expect(!applied.rewrite_required);
    var applied_parsed = try schema_api.parseValidatedTableSchema(alloc, applied.schema_json);
    defer applied_parsed.deinit(alloc);
    const applied_runtime = try schema_api.deriveRuntimeTableSchema(alloc, applied_parsed);
    defer runtime_schema.freeSchema(alloc, applied_runtime);
    const applied_email = relationalColumnForField(applied_runtime, "email", null) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("C", applied_email.collation.?);

    var duplicate_create = try lowerDdlPlanAlloc(alloc, "CREATE TABLE users (id uuid PRIMARY KEY);");
    defer duplicate_create.deinit(alloc);
    try std.testing.expectError(error.InvalidSqlCatalog, applyDdlPlanToSchemaJsonAlloc(alloc, applied.schema_json, duplicate_create));

    var duplicate_create_if_not_exists = try lowerDdlPlanAlloc(alloc, "CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY);");
    defer duplicate_create_if_not_exists.deinit(alloc);
    var unchanged = try applyDdlPlanToSchemaJsonAlloc(alloc, applied.schema_json, duplicate_create_if_not_exists);
    defer unchanged.deinit(alloc);
    try std.testing.expect(!unchanged.requires_rebuild);
    try std.testing.expect(!unchanged.validation_required);
    try std.testing.expect(!unchanged.rewrite_required);

    var table_clone = try lowerDdlPlanAlloc(alloc, "CREATE TABLE IF NOT EXISTS users_copy (LIKE users INCLUDING ALL EXCLUDING COMMENTS);");
    defer table_clone.deinit(alloc);
    const clone_plan = switch (table_clone) {
        .table_clone => |plan| plan,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqualStrings("users_copy", clone_plan.table_name);
    try std.testing.expectEqualStrings("users", clone_plan.source_table_name);
    try std.testing.expect(clone_plan.if_not_exists);
    try std.testing.expect(clone_plan.options.columns);
    try std.testing.expect(clone_plan.options.defaults);
    try std.testing.expect(clone_plan.options.generated);
    try std.testing.expect(clone_plan.options.checks);
    try std.testing.expect(clone_plan.options.constraints);
    try std.testing.expect(clone_plan.options.indexes);
    try std.testing.expect(clone_plan.options.periods);
    try std.testing.expect(clone_plan.options.update_policies);
    const clone_fingerprint = try ddlFingerprintAlloc(alloc, table_clone);
    defer alloc.free(clone_fingerprint);
    try std.testing.expectEqualStrings(
        "ddl:table_clone:table=users_copy:source=users:if_not_exists=true:columns=true:defaults=true:generated=true:checks=true:constraints=true:indexes=true:periods=true:update_policies=true",
        clone_fingerprint,
    );
    var cloned = try applyDdlPlanToSchemaJsonAlloc(alloc, applied.schema_json, table_clone);
    defer cloned.deinit(alloc);
    try std.testing.expect(cloned.requires_rebuild);
    try std.testing.expect(cloned.validation_required);
    try std.testing.expect(!cloned.rewrite_required);
    var cloned_parsed = try schema_api.parseValidatedTableSchema(alloc, cloned.schema_json);
    defer cloned_parsed.deinit(alloc);
    const cloned_runtime = try schema_api.deriveRuntimeTableSchema(alloc, cloned_parsed);
    defer runtime_schema.freeSchema(alloc, cloned_runtime);
    try std.testing.expectEqual(runtime_schema.StorageMode.relational, cloned_runtime.storage_mode);
    try std.testing.expectEqual(@as(usize, 7), cloned_runtime.relational_columns.len);
    try std.testing.expect(cloned_runtime.primary_key != null);
    try std.testing.expectEqualStrings("id", cloned_runtime.primary_key.?.columns[0]);
    try std.testing.expectEqual(@as(usize, 1), cloned_runtime.unique_constraints.len);
    try std.testing.expectEqual(@as(usize, 1), cloned_runtime.checks.len);
    const cloned_email = relationalColumnForField(cloned_runtime, "email", null) orelse return error.TestUnexpectedResult;
    try std.testing.expectEqualStrings("C", cloned_email.collation.?);
    const cloned_current_day = relationalColumnForField(cloned_runtime, "current_day_ns", null) orelse return error.TestUnexpectedResult;
    try std.testing.expect(cloned_current_day.default_value != null);

    var table_clone_without_constraints = try lowerDdlPlanAlloc(alloc, "CREATE TABLE users_copy (LIKE users);");
    defer table_clone_without_constraints.deinit(alloc);
    try std.testing.expectError(error.UnsupportedSqlShape, applyDdlPlanToSchemaJsonAlloc(alloc, applied.schema_json, table_clone_without_constraints));

    var create_view = try lowerDdlPlanAlloc(alloc, "CREATE VIEW users_v AS SELECT id, email FROM users;");
    defer create_view.deinit(alloc);
    const create_view_plan = switch (create_view) {
        .view_catalog => |plan| switch (plan) {
            .create => |create_plan| create_plan,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqualStrings("users_v", create_view_plan.view_name);
    try std.testing.expectEqualStrings("users", create_view_plan.source_table_name);
    try std.testing.expectEqual(@as(usize, 2), create_view_plan.source_fields.len);
    try std.testing.expectEqualStrings("id", create_view_plan.source_fields[0]);
    try std.testing.expectEqualStrings("email", create_view_plan.source_fields[1]);
    try std.testing.expectEqual(@as(usize, 2), create_view_plan.output_fields.len);
    try std.testing.expectEqualStrings("id", create_view_plan.output_fields[0]);
    try std.testing.expectEqualStrings("email", create_view_plan.output_fields[1]);
    const create_view_fingerprint = try ddlFingerprintAlloc(alloc, create_view);
    defer alloc.free(create_view_fingerprint);
    try std.testing.expectEqualStrings(
        "ddl:create_view:view=users_v:source=users:source_fields=2:fields=2:replace=false:if_not_exists=false",
        create_view_fingerprint,
    );
    try std.testing.expectError(error.UnsupportedSqlShape, applyDdlPlanToSchemaJsonAlloc(alloc, applied.schema_json, create_view));

    var create_view_aliases = try lowerDdlPlanAlloc(alloc, "CREATE VIEW users_v(user_id, contact_email) AS SELECT id, email FROM users;");
    defer create_view_aliases.deinit(alloc);
    const create_view_aliases_plan = switch (create_view_aliases) {
        .view_catalog => |plan| switch (plan) {
            .create => |create_plan| create_plan,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqualStrings("user_id", create_view_aliases_plan.output_fields[0]);
    try std.testing.expectEqualStrings("contact_email", create_view_aliases_plan.output_fields[1]);
    try std.testing.expectEqualStrings("id", create_view_aliases_plan.source_fields[0]);
    try std.testing.expectEqualStrings("email", create_view_aliases_plan.source_fields[1]);
    const create_view_aliases_fingerprint = try ddlFingerprintAlloc(alloc, create_view_aliases);
    defer alloc.free(create_view_aliases_fingerprint);
    try std.testing.expectEqualStrings(
        "ddl:create_view:view=users_v:source=users:source_fields=2:fields=2:replace=false:if_not_exists=false",
        create_view_aliases_fingerprint,
    );
    try std.testing.expectError(error.UnsupportedSqlShape, lowerDdlPlanAlloc(alloc, "CREATE VIEW users_v(user_id) AS SELECT id, email FROM users;"));

    var create_view_select_aliases = try lowerDdlPlanAlloc(alloc, "CREATE VIEW users_v AS SELECT id AS user_id, email contact_email FROM users;");
    defer create_view_select_aliases.deinit(alloc);
    const create_view_select_aliases_plan = switch (create_view_select_aliases) {
        .view_catalog => |plan| switch (plan) {
            .create => |create_plan| create_plan,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqualStrings("id", create_view_select_aliases_plan.source_fields[0]);
    try std.testing.expectEqualStrings("email", create_view_select_aliases_plan.source_fields[1]);
    try std.testing.expectEqualStrings("user_id", create_view_select_aliases_plan.output_fields[0]);
    try std.testing.expectEqualStrings("contact_email", create_view_select_aliases_plan.output_fields[1]);

    var create_or_replace_view = try lowerDdlPlanAlloc(alloc, "CREATE OR REPLACE VIEW users_v AS SELECT id, email FROM users;");
    defer create_or_replace_view.deinit(alloc);
    const create_or_replace_view_plan = switch (create_or_replace_view) {
        .view_catalog => |plan| switch (plan) {
            .create => |create_plan| create_plan,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expect(create_or_replace_view_plan.replace_existing);
    const create_or_replace_view_fingerprint = try ddlFingerprintAlloc(alloc, create_or_replace_view);
    defer alloc.free(create_or_replace_view_fingerprint);
    try std.testing.expectEqualStrings(
        "ddl:create_view:view=users_v:source=users:source_fields=2:fields=2:replace=true:if_not_exists=false",
        create_or_replace_view_fingerprint,
