    try std.testing.expectEqual(@as(usize, 1), lowered.query.expression_predicates[0].rhs.len);
    try std.testing.expectEqualStrings("[\"read\",\"write\"]", lowered.query.expression_predicates[0].rhs[0].value_json);

    var not_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE string_to_array(scope, ' ') != $1 ORDER BY id",
        schema,
        &.{.{ .json = "[\"read\"]" }},
    );
    defer not_lowered.deinit(alloc);

    try std.testing.expectEqual(@as(usize, 1), not_lowered.query.expression_predicates.len);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, not_lowered.query.expression_predicates[0].op);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.string_to_array, not_lowered.query.expression_predicates[0].lhs.kind);
}

test "postgres sql adapter lowers coalesce projection" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"display_name":{"type":"keyword"},"email":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id, COALESCE(display_name, email, 'unknown') AS name_or_email FROM users ORDER BY id",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expect(!lowered.query.select_all);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.select.len);
    try std.testing.expectEqualStrings("id", lowered.query.select[0]);
    try std.testing.expectEqual(@as(usize, 0), lowered.query.coalesce.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.expressions.len);
    try std.testing.expectEqualStrings("name_or_email", lowered.query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.coalesce, lowered.query.expressions[0].expression.kind);
    try std.testing.expectEqual(@as(usize, 3), lowered.query.expressions[0].expression.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, lowered.query.expressions[0].expression.operands[0].kind);
    try std.testing.expectEqualStrings("display_name", lowered.query.expressions[0].expression.operands[0].field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.value, lowered.query.expressions[0].expression.operands[2].kind);
    try std.testing.expectEqualStrings("\"unknown\"", lowered.query.expressions[0].expression.operands[2].value_json);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerSelectAlloc(
        alloc,
        "SELECT COALESCE(missing, 'unknown') AS display FROM users",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers scalar any predicates" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ANY($1::text[])",
        schema,
        &.{.{ .json = "[\"active\",\"pending\"]" }},
    );
    defer lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), lowered.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", lowered.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"active\",\"pending\"]", lowered.query.in_predicates[0].values_json);
    try std.testing.expect(!lowered.query.in_predicates[0].negated);

    var constructor_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ANY(ARRAY['active','pending']::text[])",
        schema,
        &.{},
    );
    defer constructor_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), constructor_lowered.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", constructor_lowered.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"active\",\"pending\"]", constructor_lowered.query.in_predicates[0].values_json);
    try std.testing.expect(!constructor_lowered.query.in_predicates[0].negated);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ANY($1::text[])",
        schema,
        &.{.{ .json = "[\"active\",3]" }},
    ));

    var some_lowered = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = SOME($1::text[])",
        schema,
        &.{.{ .json = "[\"active\",\"pending\"]" }},
    );
    defer some_lowered.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), some_lowered.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", some_lowered.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"active\",\"pending\"]", some_lowered.query.in_predicates[0].values_json);
    try std.testing.expect(!some_lowered.query.in_predicates[0].negated);

    var any_inequality = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status != ANY($1::text[])",
        schema,
        &.{.{ .json = "[\"archived\",\"disabled\"]" }},
    );
    defer any_inequality.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 0), any_inequality.query.in_predicates.len);
    try std.testing.expectEqual(@as(usize, 2), any_inequality.query.or_predicates.len);
    try std.testing.expectEqual(@as(usize, 1), any_inequality.query.or_predicates[0].predicates.len);
    try std.testing.expectEqualStrings("status", any_inequality.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, any_inequality.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"archived\"", any_inequality.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("\"disabled\"", any_inequality.query.or_predicates[1].predicates[0].value_json.?);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status != ANY($1::text[])",
        schema,
        &.{.{ .json = "[\"archived\",3]" }},
    ));

    var some_inequality = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status <> SOME($1::text[])",
        schema,
        &.{.{ .json = "[\"archived\",\"disabled\"]" }},
    );
    defer some_inequality.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), some_inequality.query.or_predicates.len);
    try std.testing.expectEqualStrings("status", some_inequality.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, some_inequality.query.or_predicates[0].predicates[0].op);
    try std.testing.expectEqualStrings("\"archived\"", some_inequality.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("\"disabled\"", some_inequality.query.or_predicates[1].predicates[0].value_json.?);

    var all_equal = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ALL($1::text[])",
        schema,
        &.{.{ .json = "[\"active\",\"active\"]" }},
    );
    defer all_equal.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), all_equal.query.predicates.len);
    try std.testing.expectEqualStrings("status", all_equal.query.predicates[0].field);
    try std.testing.expectEqualStrings("\"active\"", all_equal.query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("status", all_equal.query.predicates[1].field);
    try std.testing.expectEqualStrings("\"active\"", all_equal.query.predicates[1].value_json.?);
    try std.testing.expectEqual(@as(usize, 0), all_equal.query.in_predicates.len);

    var constructor_all_equal = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = ALL(ARRAY['active','active'])",
        schema,
        &.{},
    );
    defer constructor_all_equal.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 2), constructor_all_equal.query.predicates.len);
    try std.testing.expectEqualStrings("status", constructor_all_equal.query.predicates[0].field);
    try std.testing.expectEqualStrings("\"active\"", constructor_all_equal.query.predicates[0].value_json.?);

    var negated = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (status = ANY($1::text[]))",
        schema,
        &.{.{ .json = "[\"disabled\"]" }},
    );
    defer negated.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), negated.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", negated.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"disabled\"]", negated.query.in_predicates[0].values_json);
    try std.testing.expect(negated.query.in_predicates[0].negated);

    var negated_some = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE NOT (status = SOME($1::text[]))",
        schema,
        &.{.{ .json = "[\"disabled\"]" }},
    );
    defer negated_some.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), negated_some.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", negated_some.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"disabled\"]", negated_some.query.in_predicates[0].values_json);
    try std.testing.expect(negated_some.query.in_predicates[0].negated);

    var all_negative = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status <> ALL($1::text[])",
        schema,
        &.{.{ .json = "[\"archived\",\"disabled\"]" }},
    );
    defer all_negative.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), all_negative.query.in_predicates.len);
    try std.testing.expectEqualStrings("status", all_negative.query.in_predicates[0].field);
    try std.testing.expectEqualStrings("[\"archived\",\"disabled\"]", all_negative.query.in_predicates[0].values_json);
    try std.testing.expect(all_negative.query.in_predicates[0].negated);
}

