    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, distinct.query.distinct_on_expressions[0].kind);
    try std.testing.expectEqualStrings("tenant_id", distinct.query.distinct_on_expressions[0].field);
    try std.testing.expectEqual(@as(usize, 2), distinct.query.select.len);
    try std.testing.expectEqualStrings("tenant_id", distinct.query.select[0]);
    try std.testing.expectEqualStrings("id", distinct.query.select[1]);
    try std.testing.expectEqualStrings("tenant_id", distinct.query.order_by[0].field);

    var expression_distinct = try lowerSelectAlloc(
        alloc,
        "SELECT DISTINCT ON (lower(u.status)) u.id, lower(u.status) AS status_key FROM usage_records AS u ORDER BY lower(u.status) ASC, u.created_at DESC LIMIT 5",
        schema,
