    );
    defer expression_distinct.deinit(alloc);
    try std.testing.expectEqual(@as(usize, 1), expression_distinct.query.distinct_on_expressions.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression_distinct.query.distinct_on_expressions[0].kind);
    try std.testing.expectEqual(@as(usize, 2), expression_distinct.query.order_by.len);
    try std.testing.expect(expression_distinct.query.order_by[0].expression != null);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression_distinct.query.order_by[0].expression.?.kind);
    try std.testing.expectEqual(@as(u32, 5), expression_distinct.query.limit.?);
