test "postgres sql adapter lowers routine expression bindings into ddl plans" {
    const alloc = std.testing.allocator;

    const normalize_operands = [_]db_mod.types.RelationalRowsExpression{.{ .kind = .field, .field = "arg1" }};
    const normalize_expression = db_mod.types.RelationalRowsExpression{
        .kind = .lower,
        .operands = &normalize_operands,
    };
    const bindings = [_]RoutineExpressionBinding{.{
        .sql_name = "normalize_status",
        .arity = 1,
        .expression = normalize_expression,
    }};

    var generated_table = try lowerDdlPlanWithFunctionBindingsAlloc(
        alloc,
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, status_key text GENERATED ALWAYS AS (normalize_status(status)) STORED);",
        .{ .routine_expressions = &bindings },
    );
    defer generated_table.deinit(alloc);
    const generated_create = switch (generated_table) {
        .create_table => |create| create,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 3), generated_create.columns.len);
    const generated = generated_create.columns[2].generated orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(runtime_schema.RelationalGeneratedOp.expression, generated.op);
    const generated_expression = generated.expression orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, generated_expression.kind);
    try std.testing.expectEqual(@as(usize, 1), generated_expression.operands.len);
    try std.testing.expectEqualStrings("status", generated_expression.operands[0].field);

    var rewrite_table = try lowerDdlPlanWithFunctionBindingsAlloc(
        alloc,
        "ALTER TABLE usage_records ALTER COLUMN status TYPE text USING normalize_status(status);",
        .{ .routine_expressions = &bindings },
    );
    defer rewrite_table.deinit(alloc);
    const rewrite_alter = switch (rewrite_table) {
        .alter_table => |alter| alter,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), rewrite_alter.operations.len);
    const rewrite_expression = switch (rewrite_alter.operations[0]) {
        .alter_column_type => |operation| (operation.rewrite_expression orelse return error.TestUnexpectedResult).expression,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, rewrite_expression.kind);
    try std.testing.expectEqual(@as(usize, 1), rewrite_expression.operands.len);
    try std.testing.expectEqualStrings("status", rewrite_expression.operands[0].field);

    var checked_table = try lowerDdlPlanWithFunctionBindingsAlloc(
        alloc,
        "CREATE TABLE usage_records (id text PRIMARY KEY, status text, CONSTRAINT usage_records_status_check CHECK (normalize_status(status) != 'deleted'));",
        .{ .routine_expressions = &bindings },
    );
    defer checked_table.deinit(alloc);
    const checked_create = switch (checked_table) {
        .create_table => |create| create,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(@as(usize, 1), checked_create.checks.len);
    try std.testing.expectEqualStrings("usage_records_status_check", checked_create.checks[0].name);
    const checked_expression = checked_create.checks[0].expression orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, checked_expression.lhs.kind);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.ne, checked_expression.op);
    try std.testing.expectEqualStrings("status", checked_expression.lhs.operands[0].field);
    try std.testing.expectEqualStrings("\"deleted\"", checked_expression.rhs[0].value_json);

    var routine_policy = try lowerDdlPlanWithFunctionBindingsAlloc(
        alloc,
        "CREATE POLICY usage_records_normalized_policy ON usage_records USING (normalize_status(status) = 'active');",
        .{ .routine_expressions = &bindings },
    );
    defer routine_policy.deinit(alloc);
    const routine_policy_create = switch (routine_policy) {
        .row_security_catalog => |catalog_plan| switch (catalog_plan) {
            .create_policy => |create| create,
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    };
    const routine_policy_expression = switch (routine_policy_create.predicate) {
        .expression => |predicate| predicate,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, routine_policy_expression.lhs.kind);
    try std.testing.expectEqualStrings("status", routine_policy_expression.lhs.operands[0].field);
}

const TestPrimaryResolver = struct {
    row_json: []const u8,
    version: u64,
    exists: bool = true,
    resolved_key: []const u8 = "test-existing-primary",

    fn resolver(self: *@This()) relational_rows.UniqueSelectorResolver {
        return .{
            .ptr = self,
            .resolve = resolve,
            .resolve_temporal_overlap = resolveTemporalOverlap,
            .resolve_primary = primaryExists,
            .lookup_primary = lookupPrimary,
        };
    }

    fn resolve(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
    ) anyerror!?[]u8 {
        _ = table_name;
        _ = constraint_name;
        _ = encoded_value;
        const self: *@This() = @ptrCast(@alignCast(ptr));
        if (!self.exists) return null;
        return try alloc.dupe(u8, self.resolved_key);
    }

    fn resolveTemporalOverlap(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        constraint_name: []const u8,
        encoded_value: []const u8,
        encoded_start: []const u8,
        encoded_end: []const u8,
    ) anyerror!?[]u8 {
        _ = table_name;
        _ = constraint_name;
        _ = encoded_value;
        if (encoded_start.len == 0 or encoded_end.len == 0) return error.TestUnexpectedResult;
        const self: *@This() = @ptrCast(@alignCast(ptr));
        if (!self.exists) return null;
        return try alloc.dupe(u8, self.resolved_key);
    }

    fn primaryExists(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) anyerror!bool {
        _ = alloc;
        _ = table_name;
        _ = physical_key;
        const self: *@This() = @ptrCast(@alignCast(ptr));
        return self.exists;
    }

    fn lookupPrimary(
        ptr: *anyopaque,
        alloc: std.mem.Allocator,
        table_name: []const u8,
        physical_key: []const u8,
    ) anyerror!?relational_rows.ResolvedPrimaryRow {
        _ = table_name;
        if (physical_key.len == 0) return null;
        const self: *@This() = @ptrCast(@alignCast(ptr));
        return .{
            .json = try alloc.dupe(u8, self.row_json),
            .version = self.version,
        };
    }
};

const AppParityCorpusPlanFamily = sql_adapter.AppParityCorpusPlanFamily;
const AppParityDdlTag = sql_adapter.AppParityDdlTag;
const AppParityPlanSummary = sql_adapter.AppParityPlanSummary;
const AppParityCorpusEntry = sql_adapter.AppParityCorpusEntry;

fn expectOptionalUsize(expected: ?usize, actual: usize) !void {
    if (expected) |value| try std.testing.expectEqual(value, actual);
}

fn expectOptionalU32(expected: ?u32, actual: ?u32) !void {
    if (expected) |value| try std.testing.expectEqual(value, actual orelse return error.TestUnexpectedResult);
}

fn expectOptionalTableName(expected: ?[]const u8, actual: []const u8) !void {
    if (expected) |value| try std.testing.expectEqualStrings(value, actual);
}

fn expectAppParityPlan(expected: []const u8, actual: []const u8) !void {
    if (expected.len == 0) return;
    try std.testing.expectEqualStrings(expected, actual);
}

fn expectAppParityReturningRows(expected: []const []const u8, actual: []const []const u8) !void {
    if (expected.len == 0) return;
    try std.testing.expectEqual(expected.len, actual.len);
    for (expected, actual) |expected_row, actual_row| {
        try std.testing.expectEqualStrings(expected_row, actual_row);
    }
}

fn adapterNoopFingerprintAlloc(
    alloc: std.mem.Allocator,
    family: []const u8,
    reason: []const u8,
) ![]u8 {
    const diagnostic_reason = sql_adapter.classificationReasonFromToken(reason) orelse return error.TestUnexpectedResult;
    return sql_adapter.adapterNoopFingerprintAlloc(alloc, family, diagnostic_reason) catch |err| switch (err) {
        error.UnsupportedSqlShape => return error.TestUnexpectedResult,
        else => return err,
    };
}

fn expectFailClosedUnsupported(result: anytype) !void {
    if (result) |_| {
        return error.TestExpectedError;
    } else |err| switch (err) {
        error.UnsupportedSqlShape, error.InvalidSqlCatalog => return,
        else => return err,
    }
}

fn appParityLimitValue(limit: ?u32) i64 {
    return if (limit) |value| @intCast(value) else -1;
}

fn appParityBoolValue(value: bool) u8 {
    return sql_adapter.boolFingerprintValue(value);
}

fn appParityGeneratedExpressionCount(plan: CreateIndexPlan) usize {
    return if (plan.generated_expression != null) 1 else 0;
}

fn appParityGeneratedExpressionOp(plan: CreateIndexPlan) ?[]const u8 {
    const generated = plan.generated_expression orelse return null;
    return @tagName(generated.op);
}

fn createTablePlanPrimaryKeyColumnCount(plan: CreateTablePlan) usize {
    return if (plan.primary_key) |primary_key| primary_key.columns.len else 0;
}

fn createTablePlanDefaultColumnCount(plan: CreateTablePlan) usize {
    var count: usize = 0;
    for (plan.columns) |column| {
        if (column.default_value != null) count += 1;
    }
    return count;
}

fn createTablePlanGeneratedColumnCount(plan: CreateTablePlan) usize {
    var count: usize = 0;
    for (plan.columns) |column| {
        if (column.generated != null) count += 1;
    }
    return count;
}

fn createTablePlanUpdatePolicyColumnCount(plan: CreateTablePlan) usize {
    var count: usize = 0;
    for (plan.columns) |column| {
        if (column.on_update_value != null) count += 1;
    }
    return count;
}

const NamedConstraintFingerprintCounts = struct {
    primary_key: usize = 0,
    unique: usize = 0,
    foreign_key: usize = 0,
    check: usize = 0,
};

fn countNamedCreateTableConstraints(plan: CreateTablePlan) NamedConstraintFingerprintCounts {
    var counts: NamedConstraintFingerprintCounts = .{};
    if (plan.primary_key) |primary_key| {
        if (primary_key.name != null) counts.primary_key += 1;
    }
    for (plan.unique_constraints) |constraint| {
        if (constraint.name.len > 0) counts.unique += 1;
    }
    for (plan.foreign_keys) |foreign_key| {
        if (foreign_key.name.len > 0) counts.foreign_key += 1;
    }
    for (plan.checks) |check| {
        if (check.name.len > 0) counts.check += 1;
    }
    return counts;
}

fn appendNamedConstraintFingerprintsAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    counts: NamedConstraintFingerprintCounts,
) ![]u8 {
    var fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, owned_base, "pk_named", counts.primary_key);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "unique_named", counts.unique);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "fk_named", counts.foreign_key);
    return try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "check_named", counts.check);
}

const ForeignKeyOptionFingerprintCounts = struct {
    deferrable: usize = 0,
    deferred: usize = 0,
    match_full: usize = 0,
    match_partial: usize = 0,
};

fn countForeignKeyOptionFingerprints(foreign_keys: []const runtime_schema.ForeignKey) ForeignKeyOptionFingerprintCounts {
    var counts: ForeignKeyOptionFingerprintCounts = .{};
    for (foreign_keys) |foreign_key| {
        if (foreign_key.deferrable) counts.deferrable += 1;
        if (foreign_key.timing == .deferred) counts.deferred += 1;
        switch (foreign_key.match) {
            .simple => {},
            .full => counts.match_full += 1,
            .partial => counts.match_partial += 1,
        }
    }
    return counts;
}

fn addForeignKeyOptionFingerprintCounts(
    counts: *ForeignKeyOptionFingerprintCounts,
    foreign_keys: []const runtime_schema.ForeignKey,
) void {
    const next = countForeignKeyOptionFingerprints(foreign_keys);
    counts.deferrable += next.deferrable;
    counts.deferred += next.deferred;
    counts.match_full += next.match_full;
    counts.match_partial += next.match_partial;
}

fn appendForeignKeyOptionFingerprintsAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    counts: ForeignKeyOptionFingerprintCounts,
) ![]u8 {
    var fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, owned_base, "fk_deferrable", counts.deferrable);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "fk_deferred", counts.deferred);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "fk_match_full", counts.match_full);
    return try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "fk_match_partial", counts.match_partial);
}

const ConstraintTimingFingerprintCounts = struct {
    primary_key_deferrable: usize = 0,
    primary_key_deferred: usize = 0,
    unique_deferrable: usize = 0,
    unique_deferred: usize = 0,
};

fn addPrimaryKeyTimingFingerprintCount(counts: *ConstraintTimingFingerprintCounts, primary_key: runtime_schema.PrimaryKey) void {
    if (primary_key.deferrable) counts.primary_key_deferrable += 1;
    if (primary_key.timing == .deferred) counts.primary_key_deferred += 1;
}

fn addUniqueTimingFingerprintCounts(counts: *ConstraintTimingFingerprintCounts, unique_constraints: []const runtime_schema.UniqueConstraint) void {
    for (unique_constraints) |constraint| {
        if (constraint.deferrable) counts.unique_deferrable += 1;
        if (constraint.timing == .deferred) counts.unique_deferred += 1;
    }
}

fn countCreateTableConstraintTimingFingerprints(plan: CreateTablePlan) ConstraintTimingFingerprintCounts {
    var counts: ConstraintTimingFingerprintCounts = .{};
    if (plan.primary_key) |primary_key| addPrimaryKeyTimingFingerprintCount(&counts, primary_key);
    addUniqueTimingFingerprintCounts(&counts, plan.unique_constraints);
    return counts;
}

fn appendConstraintTimingFingerprintsAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    counts: ConstraintTimingFingerprintCounts,
) ![]u8 {
    var fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, owned_base, "pk_deferrable", counts.primary_key_deferrable);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "pk_deferred", counts.primary_key_deferred);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "unique_deferrable", counts.unique_deferrable);
    return try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "unique_deferred", counts.unique_deferred);
}

const AlterTablePlanFingerprintCounts = struct {
    add_column: usize = 0,
    add_column_if_not_exists: usize = 0,
    add_column_default: usize = 0,
    add_column_generated: usize = 0,
    add_column_update_policy: usize = 0,
    add_column_unique: usize = 0,
    add_column_fk: usize = 0,
    add_column_check: usize = 0,
    add_period: usize = 0,
    add_primary_key: usize = 0,
    rename_column: usize = 0,
    rename_constraint: usize = 0,
    drop_column: usize = 0,
    drop_column_if_exists: usize = 0,
    drop_constraint: usize = 0,
    drop_constraint_if_exists: usize = 0,
    drop_update_policy: usize = 0,
    drop_update_policy_if_exists: usize = 0,
    set_default: usize = 0,
    drop_default: usize = 0,
    set_not_null: usize = 0,
    drop_not_null: usize = 0,
    alter_type: usize = 0,
    alter_type_rewrite_expr: usize = 0,
    add_unique: usize = 0,
    add_foreign_key: usize = 0,
    add_check: usize = 0,
    validate_constraint: usize = 0,
    constraint_timing: ConstraintTimingFingerprintCounts = .{},
    foreign_key_options: ForeignKeyOptionFingerprintCounts = .{},
};

fn alterTablePlanFingerprintCounts(plan: AlterTablePlan) AlterTablePlanFingerprintCounts {
    var counts: AlterTablePlanFingerprintCounts = .{};
    for (plan.operations) |operation| switch (operation) {
        .add_column => |add| {
            counts.add_column += 1;
            if (add.if_not_exists) counts.add_column_if_not_exists += 1;
            if (add.column.default_value != null) counts.add_column_default += 1;
            if (add.column.generated != null) counts.add_column_generated += 1;
            if (add.column.on_update_value != null) counts.add_column_update_policy += 1;
            counts.add_column_unique += add.unique_constraints.len;
            counts.add_column_fk += add.foreign_keys.len;
            counts.add_column_check += add.checks.len;
            addUniqueTimingFingerprintCounts(&counts.constraint_timing, add.unique_constraints);
            addForeignKeyOptionFingerprintCounts(&counts.foreign_key_options, add.foreign_keys);
        },
        .add_period => counts.add_period += 1,
        .add_primary_key => |primary_key| {
            counts.add_primary_key += 1;
            addPrimaryKeyTimingFingerprintCount(&counts.constraint_timing, primary_key);
        },
        .rename_column => counts.rename_column += 1,
        .rename_constraint => counts.rename_constraint += 1,
        .drop_column => |drop| {
            counts.drop_column += 1;
            if (drop.if_exists) counts.drop_column_if_exists += 1;
        },
        .drop_constraint => |drop| {
            counts.drop_constraint += 1;
            if (drop.if_exists) counts.drop_constraint_if_exists += 1;
        },
        .drop_update_policy => |drop| {
            counts.drop_update_policy += 1;
            if (drop.if_exists) counts.drop_update_policy_if_exists += 1;
        },
        .alter_column_default => |alter| {
            if (alter.default_value != null) {
                counts.set_default += 1;
            } else {
                counts.drop_default += 1;
            }
        },
        .alter_column_nullability => |alter| {
            if (alter.nullable) {
                counts.drop_not_null += 1;
            } else {
                counts.set_not_null += 1;
            }
        },
        .alter_column_type => |alter| {
            counts.alter_type += 1;
            if (alter.rewrite_expression != null) counts.alter_type_rewrite_expr += 1;
        },
        .add_unique_constraint => |constraint| {
            counts.add_unique += 1;
            addUniqueTimingFingerprintCounts(&counts.constraint_timing, &.{constraint});
        },
        .add_foreign_key => |foreign_key| {
            counts.add_foreign_key += 1;
            addForeignKeyOptionFingerprintCounts(&counts.foreign_key_options, &.{foreign_key});
        },
        .add_check => counts.add_check += 1,
        .validate_constraint => counts.validate_constraint += 1,
    };
    return counts;
}

fn sqlJoinTypeFingerprintName(join_type: db_mod.types.RelationalRowsJoinType) []const u8 {
    return switch (join_type) {
        .inner => "inner",
        .left => "left",
    };
}

fn queryFingerprintAlloc(alloc: std.mem.Allocator, family: []const u8, table_name: []const u8, query: db_mod.types.RelationalRowsQueryRequest, ctes: usize) ![]u8 {
    const claim = if (query.row_claim) |claim_value| sqlRowClaimFingerprintName(claim_value) else "none";
    const order_expr = expressionOrderCount(query.order_by);
    const distinct_on_count = query.distinct_on.len + query.distinct_on_expressions.len;
    if (distinct_on_count > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:distinct_on={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                distinct_on_count,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (ctes > 0 or query.source_cte.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:source_cte={d}:pred={d}:array_any={d}:expr_pred={d}:expr_or={d}:expr_not={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                @as(u8, if (query.source_cte.len > 0) 1 else 0),
                query.predicates.len,
                query.array_any.len,
                query.expression_predicates.len,
                query.expression_or_predicates.len,
                query.expression_not_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (query.array_any.len > 0 or query.expression_or_predicates.len > 0 or query.expression_not_predicates.len > 0) {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:array_any={d}:expr_pred={d}:expr_or={d}:expr_not={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.array_any.len,
                query.expression_predicates.len,
                query.expression_or_predicates.len,
                query.expression_not_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                appParityLimitValue(query.limit),
                claim,
            },
        );
    }
    if (query.expression_array_contains.len > 0) {
        if (query.limit) |limit| {
            return try std.fmt.allocPrint(
                alloc,
                "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
                .{
                    family,
                    table_name,
                    ctes,
                    query.predicates.len,
                    query.expression_predicates.len,
                    query.expression_array_contains.len,
                    query.json_path_eq.len,
                    query.or_predicates.len,
                    query.not_predicates.len,
                    query.select.len,
                    query.expressions.len,
                    query.field_aliases.len,
                    query.order_by.len,
                    order_expr,
                    limit,
                    claim,
                },
            );
        }
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:expr_array={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit=none:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.expression_array_contains.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                claim,
            },
        );
    }
    if (query.text_patterns.len > 0) {
        if (query.limit) |limit| {
            return try std.fmt.allocPrint(
                alloc,
                "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:text_pattern={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
                .{
                    family,
                    table_name,
                    ctes,
                    query.predicates.len,
                    query.expression_predicates.len,
                    query.json_path_eq.len,
                    query.text_patterns.len,
                    query.or_predicates.len,
                    query.not_predicates.len,
                    query.select.len,
                    query.expressions.len,
                    query.field_aliases.len,
                    query.order_by.len,
                    order_expr,
                    limit,
                    claim,
                },
            );
        }
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:text_pattern={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit=none:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.text_patterns.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                claim,
            },
        );
    }
    if (query.limit) |limit| {
        return try std.fmt.allocPrint(
            alloc,
            "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit={d}:claim={s}",
            .{
                family,
                table_name,
                ctes,
                query.predicates.len,
                query.expression_predicates.len,
                query.json_path_eq.len,
                query.or_predicates.len,
                query.not_predicates.len,
                query.select.len,
                query.expressions.len,
                query.field_aliases.len,
                query.order_by.len,
                order_expr,
                limit,
                claim,
            },
        );
    }
    return try std.fmt.allocPrint(
        alloc,
        "{s}:table={s}:ctes={d}:pred={d}:expr_pred={d}:json_eq={d}:or={d}:not={d}:select={d}:expr={d}:alias={d}:order={d}:order_expr={d}:limit=none:claim={s}",
        .{
            family,
            table_name,
            ctes,
            query.predicates.len,
            query.expression_predicates.len,
            query.json_path_eq.len,
            query.or_predicates.len,
            query.not_predicates.len,
            query.select.len,
            query.expressions.len,
            query.field_aliases.len,
            query.order_by.len,
            order_expr,
            claim,
        },
    );
}

fn appendQueryAccessPathFingerprintAlloc(
    alloc: std.mem.Allocator,
    owned_base: []u8,
    query: db_mod.types.RelationalRowsQueryRequest,
) ![]u8 {
    var fingerprint = owned_base;
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "in", query.in_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "json_contains", query.json_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "json_exists", query.json_path_exists.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "array_contains", query.array_contains.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "array_eq", query.array_eq.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "access_or", query.access_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "access_not", query.access_not_predicates.len);
    return fingerprint;
}

