            right.predicates.len,
            right.array_any.len,
            right.expression_predicates.len,
            right.expression_or_predicates.len,
            right.expression_not_predicates.len,
            right.expression_array_contains.len,
            right.json_path_eq.len,
            right.text_patterns.len,
            right.order_by.len,
            expressionOrderCount(right.order_by),
            appParityLimitValue(right.limit),
            lowered.plan.lateral.correlations.len,
            lowered.plan.lateral.select.len,
            lowered.plan.lateral.order_by.len,
            expressionOrderCount(lowered.plan.lateral.order_by),
            appParityLimitValue(lowered.plan.lateral.limit),
        },
    );
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "left_source_cte", if (left.source_cte.len > 0) 1 else 0);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "right_source_cte", if (right.source_cte.len > 0) 1 else 0);
    fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.ctes);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "left", left);
    fingerprint = try appendSideQueryAccessOnlyFingerprintAlloc(alloc, fingerprint, "right", right);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_pred", lowered.plan.lateral.match_expression_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_or", lowered.plan.lateral.match_expression_or_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_not", lowered.plan.lateral.match_expression_not_predicates.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "match_expr_array", lowered.plan.lateral.match_expression_array_contains.len);
    return fingerprint;
}

fn readFingerprintWithPrefixAlloc(
    alloc: std.mem.Allocator,
    owned_fingerprint: []u8,
    family: []const u8,
) ![]u8 {
    defer alloc.free(owned_fingerprint);
    return try std.fmt.allocPrint(alloc, "read:{s}:{s}", .{ family, owned_fingerprint });
}

fn relationPopulationFingerprintAlloc(
    alloc: std.mem.Allocator,
    lowered: LoweredRelationPopulationPlan,
) ![]u8 {
    const source = try readPlanFingerprintAlloc(alloc, lowered.source);
    defer alloc.free(source);
    return try std.fmt.allocPrint(
        alloc,
        "relation_population:mode={s}:target={s}:lifetime={s}:if_not_exists={}:populate={}:source={s}",
        .{ relationPopulationModeName(lowered.mode), lowered.target_table_name, relationPopulationTargetLifetimeName(lowered.target_lifetime), lowered.if_not_exists, lowered.populate, source },
    );
}

fn relationPopulationModeName(mode: RelationPopulationMode) []const u8 {
    return switch (mode) {
        .create_table_as => "create_table_as",
        .select_into => "select_into",
    };
}

fn relationPopulationTargetLifetimeName(kind: ?RelationLifetimeKind) []const u8 {
    return if (kind) |lifetime| relationLifetimeKindName(lifetime) else "durable";
}

fn writePlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredWritePlan) ![]u8 {
    return switch (lowered) {
        .insert => |insert| blk: {
            const operations = transformOperationCount(insert.batch.transforms);
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "insert:table={s}:writes={d}:transforms={d}:ops={d}:deletes={d}:returning_rows={d}:returning_expr={d}",
                .{
                    insert.table_name,
                    insert.batch.writes.len,
                    insert.batch.transforms.len,
                    operations,
                    insert.batch.deletes.len,
                    insert.batch.returning_rows.len,
                    insert.returning_expression_count,
                },
            );
            fingerprint = try appendTransformOpFingerprintAlloc(alloc, fingerprint, insert.batch.transforms);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", insert.returning_all);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", insert.conflict_where);
            break :blk fingerprint;
        },
        .insert_source => |insert_source| blk: {
            var fingerprint = try insertSourceFingerprintAlloc(alloc, insert_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", insert_source.insert_source.req.source.offset);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "conflict_where", insert_source.conflict_where);
            break :blk fingerprint;
        },
        .recursive_insert_source => |recursive_insert_source| blk: {
            break :blk try recursiveInsertSourceFingerprintAlloc(alloc, recursive_insert_source);
        },
        .update => |update| blk: {
            const operations = transformOperationCount(update.batch.transforms);
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "update:table={s}:transforms={d}:ops={d}:returning_rows={d}:returning_expr={d}",
                .{ update.table_name, update.batch.transforms.len, operations, update.batch.returning_rows.len, update.returning_expression_count },
            );
            fingerprint = try appendTransformOpFingerprintAlloc(alloc, fingerprint, update.batch.transforms);
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "writes", update.batch.writes.len);
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "deletes", update.batch.deletes.len);
            fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "identity_rewrites", update.batch.relational_identity_rewrites.len);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", update.returning_all);
            break :blk fingerprint;
        },
        .delete => |delete| blk: {
            var fingerprint = try std.fmt.allocPrint(
                alloc,
                "delete:table={s}:deletes={d}:returning_rows={d}:returning_expr={d}",
                .{ delete.table_name, delete.batch.deletes.len, delete.batch.returning_rows.len, delete.returning_expression_count },
            );
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "returning_all", delete.returning_all);
            break :blk fingerprint;
        },
        .update_source => |update_source| blk: {
            var fingerprint = try updateSourceFingerprintAlloc(alloc, update_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", update_source.mutation.req.source.offset);
            break :blk fingerprint;
        },
        .delete_source => |delete_source| blk: {
            var fingerprint = try deleteSourceFingerprintAlloc(alloc, delete_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", delete_source.mutation.req.source.offset);
            break :blk fingerprint;
        },
        .truncate_source => |truncate_source| blk: {
            var fingerprint = try truncateSourceFingerprintAlloc(alloc, truncate_source);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "source_offset", truncate_source.mutation.req.source.offset);
            break :blk fingerprint;
        },
        .update_joined_source => |update_joined_source| try joinedSourceFingerprintAlloc(alloc, "update_joined_source", update_joined_source),
        .delete_joined_source => |delete_joined_source| try joinedSourceFingerprintAlloc(alloc, "delete_joined_source", delete_joined_source),
        .recursive_update_joined_source => |recursive_update_joined_source| try recursiveJoinedSourceFingerprintAlloc(alloc, "update_joined_source", recursive_update_joined_source),
        .recursive_delete_joined_source => |recursive_delete_joined_source| try recursiveJoinedSourceFingerprintAlloc(alloc, "delete_joined_source", recursive_delete_joined_source),
        .merge_mutation => |merge| try mergeMutationFingerprintAlloc(alloc, merge),
        .recursive_merge_mutation => |recursive_merge| try recursiveMergeMutationFingerprintAlloc(alloc, recursive_merge),
    };
}

fn windowFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredWindowPlan) ![]u8 {
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "window:table={s}:ctes={d}:source_cte={d}:source_pred={d}:windows={d}:window_expr={d}:window_default={d}:window_frame_sig={d}:select={d}:order={d}:limit={d}",
        .{
            lowered.table_name,
            lowered.plan.ctes.len,
            @as(u8, if (lowered.plan.window.source.source_cte.len > 0) 1 else 0),
            lowered.plan.window.source.predicates.len,
            lowered.plan.window.windows.len,
            windowValueExpressionCount(lowered.plan.window.windows),
            windowDefaultCount(lowered.plan.window.windows),
            windowFrameSignature(lowered.plan.window.windows),
            lowered.plan.window.select.len,
            lowered.plan.window.order_by.len,
            appParityLimitValue(lowered.plan.window.limit),
        },
    );
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "order_expr", expressionOrderCount(lowered.plan.window.order_by));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter", windowFilterPredicateCount(lowered.plan.window.windows));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter_expr", windowFilterExpressionCount(lowered.plan.window.windows));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter_access", windowFilterAccessCount(lowered.plan.window.windows));
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "window_filter_groups", windowFilterGroupCount(lowered.plan.window.windows));
    fingerprint = try appendSourceQueryAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.window.source);
    fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, lowered.plan.ctes);
    fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lowered.plan.window.offset);
    return fingerprint;
}

fn readPlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredReadPlan) ![]u8 {
    return switch (lowered) {
        .query => |query| blk: {
            var fingerprint = try queryFingerprintAlloc(alloc, "query", query.table_name, query.plan.query, query.plan.ctes.len);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", query.plan.query.offset);
            fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "select_all", query.plan.query.select_all);
            fingerprint = try appendQueryAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.query);
            fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.ctes);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "query");
        },
        .set_operation => |set_operation| blk: {
            const fingerprint = try setOperationFingerprintAlloc(alloc, set_operation);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "set_operation");
        },
        .recursive_cte => |recursive_cte| blk: {
            const fingerprint = try recursiveCteFingerprintAlloc(alloc, recursive_cte);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "recursive_cte");
        },
        .aggregate => |aggregate| blk: {
            var fingerprint = try aggregatePlanFingerprintAlloc(alloc, aggregate);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", aggregate.plan.aggregate.offset);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "aggregate");
        },
        .join => |join| blk: {
            var fingerprint = try joinFingerprintAlloc(alloc, join);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", join.join.offset);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "join");
        },
        .lateral => |lateral| blk: {
            var fingerprint = try lateralFingerprintAlloc(alloc, lateral);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "right_offset", lateral.plan.lateral.right.offset);
            fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lateral.plan.lateral.offset);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "lateral");
        },
        .window => |window| blk: {
            const fingerprint = try windowFingerprintAlloc(alloc, window);
            break :blk try readFingerprintWithPrefixAlloc(alloc, fingerprint, "window");
        },
    };
}

fn recursiveCteFingerprintAlloc(alloc: std.mem.Allocator, recursive_cte: LoweredRecursiveCtePlan) ![]u8 {
    const anchor = try queryFingerprintAlloc(alloc, "anchor", recursive_cte.anchor.table_name, recursive_cte.anchor.plan.query, recursive_cte.anchor.plan.ctes.len);
    defer alloc.free(anchor);
    const member = try recursiveCteMemberFingerprintAlloc(alloc, recursive_cte.recursive_member);
    defer alloc.free(member);
    return try std.fmt.allocPrint(
        alloc,
        "recursive_cte:name={s}:op={s}:anchor={s}:member={s}:outputs={d}:self_ref={}:max_rows={d}:max_bytes={d}:spill_after={d}",
        .{
            recursive_cte.cte_name,
            @tagName(recursive_cte.operation),
            anchor,
            member,
            recursive_cte.output_columns.len,
            recursive_cte.recursive_member_references_cte,
            recursive_cte.max_rows orelse 0,
            recursive_cte.max_bytes orelse 0,
            recursive_cte.spill_after_bytes orelse 0,
        },
    );
}

fn recursiveCteMemberFingerprintAlloc(alloc: std.mem.Allocator, member: LoweredRecursiveCteMemberPlan) ![]u8 {
    return switch (member) {
        .join => |join| try std.fmt.allocPrint(
            alloc,
            "recursive_member_join:type={s}:left={s}:right={s}:on={d}:projections={d}",
            .{ sqlJoinTypeFingerprintName(join.join_type), join.left_table_name, join.right_table_name, join.on.len, join.projections.len },
        ),
    };
}

fn setOperationFingerprintAlloc(alloc: std.mem.Allocator, set_operation: LoweredSetOperationPlan) ![]u8 {
    const left = try queryFingerprintAlloc(alloc, "left", set_operation.left.table_name, set_operation.left.plan.query, set_operation.left.plan.ctes.len);
    defer alloc.free(left);
    const right = try queryFingerprintAlloc(alloc, "right", set_operation.right.table_name, set_operation.right.plan.query, set_operation.right.plan.ctes.len);
    defer alloc.free(right);
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "set_operation:op={s}:left={s}:right={s}",
        .{ @tagName(set_operation.operation), left, right },
    );
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "result_output", set_operation.output_columns.len);
    fingerprint = try appendNonZeroUsizeFingerprintAlloc(alloc, fingerprint, "result_order", set_operation.order_by.len);
    if (set_operation.limit) |limit| fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "result_limit", limit);
    fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "result_offset", set_operation.offset);
    return fingerprint;
}

fn explainPlanFingerprintAlloc(alloc: std.mem.Allocator, lowered: LoweredExplainPlan) ![]u8 {
    var subject_kind: []const u8 = undefined;
    const inner = switch (lowered.subject) {
        .read => |read| blk: {
            subject_kind = "read";
            break :blk try readPlanFingerprintAlloc(alloc, read);
        },
        .write => |write| blk: {
            subject_kind = "write";
            break :blk try writePlanFingerprintAlloc(alloc, write);
        },
    };
    defer alloc.free(inner);
    var fingerprint = try std.fmt.allocPrint(
        alloc,
        "explain:kind={s}:analyze={}:inner={s}",
        .{ subject_kind, lowered.analyze, inner },
    );
    if (lowered.format != .text) {
        fingerprint = try appendStringFingerprintAlloc(
            alloc,
            fingerprint,
            "format",
            explainFormatName(lowered.format),
        );
    }
    if (lowered.verbose) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "verbose", lowered.verbose);
    }
    if (!lowered.costs) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "costs", lowered.costs);
    }
    if (lowered.buffers) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "buffers", lowered.buffers);
    }
    if (!lowered.timing) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "timing", lowered.timing);
    }
    if (!lowered.summary) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "summary", lowered.summary);
    }
    if (lowered.settings) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "settings", lowered.settings);
    }
    if (lowered.wal) {
        fingerprint = try appendBoolFingerprintAlloc(alloc, fingerprint, "wal", lowered.wal);
    }
    return fingerprint;
}

fn explainFormatName(format: ExplainFormat) []const u8 {
    return switch (format) {
        .text => "text",
        .json => "json",
    };
}

fn lowerAppParityReadPlanAlloc(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
) !LoweredReadPlan {
    var catalog_opt = try sql_adapter.appParityCatalogForEntryAlloc(alloc, entry);
    if (catalog_opt) |*catalog| {
        defer catalog.deinit(alloc);
        return try lowerReadPlanWithCatalogAlloc(
            alloc,
            entry.sql,
            effective_schema,
            entry.params,
            catalog.iface(),
        );
    }
    return try lowerReadPlanAlloc(alloc, entry.sql, effective_schema, entry.params);
}

fn lowerAppParityExplainPlanAlloc(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
    unique_resolver: relational_rows.UniqueSelectorResolver,
    row_claim: db_mod.types.RowClaimRequest,
) !LoweredExplainPlan {
    var catalog_opt = try sql_adapter.appParityCatalogForEntryAlloc(alloc, entry);
    if (catalog_opt) |*catalog| {
        defer catalog.deinit(alloc);
        return try lowerExplainPlanWithOptionsCatalogAndFunctionBindingsAlloc(
            alloc,
            entry.sql,
            effective_schema,
            entry.params,
            .{
                .unique_resolver = unique_resolver,
                .row_claim = row_claim,
            },
            catalog.iface(),
            .{},
        );
    }
    return try lowerExplainPlanWithOptionsAlloc(alloc, entry.sql, effective_schema, entry.params, .{
        .unique_resolver = unique_resolver,
        .row_claim = row_claim,
    });
}

fn expectAppParityReadPlanEntry(
    alloc: std.mem.Allocator,
    effective_schema: runtime_schema.TableSchema,
    entry: AppParityCorpusEntry,
) !void {
    var lowered = try lowerAppParityReadPlanAlloc(alloc, effective_schema, entry);
    defer lowered.deinit(alloc);
    try expectAppParityReadSummary(entry.summary, lowered);

    switch (entry.family) {
        .query => switch (lowered) {
            .query => |query| {
                var fingerprint = try queryFingerprintAlloc(alloc, "query", query.table_name, query.plan.query, query.plan.ctes.len);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", query.plan.query.offset);
                fingerprint = try appendTrueBoolFingerprintAlloc(alloc, fingerprint, "select_all", query.plan.query.select_all);
                fingerprint = try appendQueryAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.query);
                fingerprint = try appendCteAccessPathFingerprintAlloc(alloc, fingerprint, query.plan.ctes);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .read => {
            const fingerprint = try readPlanFingerprintAlloc(alloc, lowered);
            defer alloc.free(fingerprint);
            try expectAppParityPlan(entry.plan, fingerprint);
        },
        .aggregate => switch (lowered) {
            .aggregate => |aggregate| {
                var fingerprint = try aggregatePlanFingerprintAlloc(alloc, aggregate);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", aggregate.plan.aggregate.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .join => switch (lowered) {
            .join => |join| {
                var fingerprint = try joinFingerprintAlloc(alloc, join);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", join.join.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .lateral => switch (lowered) {
            .lateral => |lateral| {
                var fingerprint = try lateralFingerprintAlloc(alloc, lateral);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "right_offset", lateral.plan.lateral.right.offset);
                fingerprint = try appendNonZeroU32FingerprintAlloc(alloc, fingerprint, "offset", lateral.plan.lateral.offset);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        .window => switch (lowered) {
            .window => |window| {
                const fingerprint = try windowFingerprintAlloc(alloc, window);
                defer alloc.free(fingerprint);
                try expectAppParityPlan(entry.plan, fingerprint);
            },
            else => return error.TestUnexpectedResult,
        },
        else => return error.TestUnexpectedResult,
    }
}

fn expectAppParityReadSummary(summary: AppParityPlanSummary, lowered: LoweredReadPlan) !void {
    switch (lowered) {
        .query => |query| {
            try expectOptionalTableName(summary.table_name, query.table_name);
            try expectOptionalUsize(summary.ctes, query.plan.ctes.len);
            try expectQuerySummary(summary, query.plan.query);
        },
        .set_operation => |set_operation| {
            try expectOptionalTableName(summary.table_name, set_operation.left.table_name);
            try expectOptionalUsize(summary.ctes, set_operation.left.plan.ctes.len + set_operation.right.plan.ctes.len);
            try expectOptionalUsize(summary.select, set_operation.left.plan.query.select.len);
            try expectOptionalUsize(summary.order_by, set_operation.left.plan.query.order_by.len + set_operation.right.plan.query.order_by.len + set_operation.order_by.len);
            try expectOptionalU32(summary.limit, set_operation.limit orelse set_operation.left.plan.query.limit);
            if (summary.offset) |expected| try std.testing.expectEqual(expected, if (set_operation.offset != 0) set_operation.offset else set_operation.left.plan.query.offset);
            if (summary.right_offset) |expected| try std.testing.expectEqual(expected, set_operation.right.plan.query.offset);
        },
        .recursive_cte => |recursive_cte| {
            try expectOptionalTableName(summary.table_name, recursive_cte.anchor.table_name);
            try expectOptionalUsize(summary.ctes, 1);
            try expectOptionalUsize(summary.select, recursive_cte.anchor.plan.query.select.len);
            try expectOptionalUsize(summary.order_by, recursive_cte.anchor.plan.query.order_by.len);
            try expectOptionalU32(summary.limit, recursive_cte.anchor.plan.query.limit);
        },
        .aggregate => |aggregate| {
            try expectOptionalTableName(summary.table_name, aggregate.table_name);
            try expectOptionalUsize(summary.ctes, aggregate.plan.ctes.len);
            try expectQuerySourceSummary(summary, aggregate.plan.aggregate.source);
            try expectOptionalUsize(summary.group_by, aggregate.plan.aggregate.group_by.len);
            try expectOptionalUsize(summary.group_expressions, aggregate.plan.aggregate.group_expressions.len);
            try expectOptionalUsize(summary.aggregations, aggregate.plan.aggregate.aggregations.len);
            try expectOptionalUsize(summary.filter_groups, aggregateFilterGroupCount(aggregate.plan.aggregate.aggregations));
            try expectOptionalUsize(summary.having, aggregate.plan.aggregate.having_predicates.len);
            try expectOptionalUsize(summary.having_expressions, aggregate.plan.aggregate.having_expressions.len);
            try expectOptionalUsize(summary.having_any, aggregate.plan.aggregate.having_any.len);
            try expectOptionalUsize(summary.having_not, aggregate.plan.aggregate.having_not.len);
            try expectOptionalUsize(summary.order_by, aggregate.plan.aggregate.order_by.len);
            try expectOptionalU32(summary.limit, aggregate.plan.aggregate.limit);
            if (summary.offset) |expected| try std.testing.expectEqual(expected, aggregate.plan.aggregate.offset);
        },
        .join => |join| {
            try expectOptionalTableName(summary.table_name, join.left_table_name);
            try expectCombinedQuerySourceSummary(summary, join.join.left, join.join.right);
            try expectOptionalUsize(summary.join_on, join.join.on.len);
            try expectOptionalUsize(summary.join_select, join.join.select.len);
            try expectOptionalUsize(summary.order_by, join.join.order_by.len);
            try expectOptionalU32(summary.limit, join.join.limit);
            if (summary.offset) |expected| try std.testing.expectEqual(expected, join.join.offset);
        },
        .lateral => |lateral| {
            try expectOptionalTableName(summary.table_name, lateral.left_table_name);
            try expectCombinedQuerySourceSummary(summary, lateral.plan.lateral.left, lateral.plan.lateral.right);
            try expectOptionalUsize(summary.lateral_correlations, lateral.plan.lateral.correlations.len);
            try expectOptionalUsize(summary.join_select, lateral.plan.lateral.select.len);
            try expectOptionalUsize(summary.order_by, lateral.plan.lateral.order_by.len);
            try expectOptionalU32(summary.limit, lateral.plan.lateral.limit);
            if (summary.offset) |expected| try std.testing.expectEqual(expected, lateral.plan.lateral.offset);
            if (summary.right_offset) |expected| try std.testing.expectEqual(expected, lateral.plan.lateral.right.offset);
        },
        .window => |window| {
            try expectOptionalTableName(summary.table_name, window.table_name);
            try expectOptionalUsize(summary.ctes, window.plan.ctes.len);
            try expectQuerySourceSummary(summary, window.plan.window.source);
            try expectOptionalUsize(summary.windows, window.plan.window.windows.len);
            try expectOptionalUsize(summary.select, window.plan.window.select.len);
            try expectOptionalUsize(summary.order_by, window.plan.window.order_by.len);
            try expectOptionalU32(summary.limit, window.plan.window.limit);
            if (summary.offset) |expected| try std.testing.expectEqual(expected, window.plan.window.offset);
        },
    }
}

fn expectAppParityWriteSummary(summary: AppParityPlanSummary, lowered: LoweredWritePlan) !void {
    switch (lowered) {
        .insert => |insert| {
            try expectOptionalTableName(summary.table_name, insert.table_name);
            try expectOptionalUsize(summary.operations, transformOperationCount(insert.batch.transforms));
            try expectOptionalUsize(summary.returning, insert.batch.returning_rows.len);
            if (summary.returning_all) |expected| try std.testing.expectEqual(expected, insert.returning_all);
            if (summary.conflict_where) |expected| try std.testing.expectEqual(expected, insert.conflict_where);
        },
        .insert_source => |insert_source| {
            try expectOptionalTableName(summary.table_name, insert_source.table_name);
            try expectOptionalUsize(summary.ctes, insert_source.ctes.len);
            try expectQuerySummary(summary, insert_source.insert_source.req.source);
            try expectOptionalUsize(summary.operations, insert_source.insert_source.req.assignments.len);
            const conflict_patch_expressions = if (insert_source.insert_source.req.on_conflict) |conflict| conflict.patch_expressions.len else 0;
            const conflict_increment_expressions = if (insert_source.insert_source.req.on_conflict) |conflict| conflict.increment_expressions.len else 0;
            const conflict_json_set_expressions = if (insert_source.insert_source.req.on_conflict) |conflict| conflict.json_set_expressions.len else 0;
            try expectOptionalUsize(summary.patch_expressions, conflict_patch_expressions);
            try expectOptionalUsize(summary.increment_expressions, conflict_increment_expressions);
            try expectOptionalUsize(summary.json_set_expressions, conflict_json_set_expressions);
            try expectOptionalUsize(summary.returning, insert_source.insert_source.req.returning.len);
            if (summary.returning_all) |expected| try std.testing.expectEqual(expected, insert_source.insert_source.req.returning_all);
            if (summary.conflict_where) |expected| try std.testing.expectEqual(expected, insert_source.conflict_where);
        },
        .recursive_insert_source => |recursive_insert_source| {
            try expectOptionalTableName(summary.table_name, recursive_insert_source.insert_source.table_name);
            try expectOptionalUsize(summary.ctes, 1);
            try expectQuerySummary(summary, recursive_insert_source.insert_source.insert_source.req.source);
            try expectOptionalUsize(summary.operations, recursive_insert_source.insert_source.insert_source.req.assignments.len);
            const conflict_patch_expressions = if (recursive_insert_source.insert_source.insert_source.req.on_conflict) |conflict| conflict.patch_expressions.len else 0;
            const conflict_increment_expressions = if (recursive_insert_source.insert_source.insert_source.req.on_conflict) |conflict| conflict.increment_expressions.len else 0;
            const conflict_json_set_expressions = if (recursive_insert_source.insert_source.insert_source.req.on_conflict) |conflict| conflict.json_set_expressions.len else 0;
            try expectOptionalUsize(summary.patch_expressions, conflict_patch_expressions);
            try expectOptionalUsize(summary.increment_expressions, conflict_increment_expressions);
            try expectOptionalUsize(summary.json_set_expressions, conflict_json_set_expressions);
            try expectOptionalUsize(summary.returning, recursive_insert_source.insert_source.insert_source.req.returning.len);
            if (summary.returning_all) |expected| try std.testing.expectEqual(expected, recursive_insert_source.insert_source.insert_source.req.returning_all);
            if (summary.conflict_where) |expected| try std.testing.expectEqual(expected, recursive_insert_source.insert_source.conflict_where);
        },
        .update => |update| {
            try expectOptionalTableName(summary.table_name, update.table_name);
            try expectOptionalUsize(summary.operations, transformOperationCount(update.batch.transforms));
            try expectOptionalUsize(summary.returning, update.batch.returning_rows.len);
            if (summary.returning_all) |expected| try std.testing.expectEqual(expected, update.returning_all);
        },
        .delete => |delete| {
            try expectOptionalTableName(summary.table_name, delete.table_name);
