test "app parity cte coverage tokens are exact" {
    const malformed = "query:table=usage_records:ctes=1:cte0_expr_pred=2x";
    try std.testing.expect(!sql_adapter.planHasNonZeroUsizeTokenNamePrefix(malformed, "cte0_"));
    try std.testing.expect(!sql_adapter.planHasNonZeroUsizeTokenNamePrefix(malformed, "cte0_expr_"));
    try std.testing.expect(!sql_adapter.planHasNonZeroUsizeTokenNamePrefix("query:table=usage_records:ctes=1:cte0_expr_pred=0", "cte0_expr_"));
    try std.testing.expect(sql_adapter.planHasNonZeroUsizeTokenNamePrefix("query:table=usage_records:ctes=1:cte0_expr_pred=2", "cte0_expr_"));

    var coverage = AppParityCorpusCoverage{};
    try coverage.observe(std.testing.allocator, .{
        .family = .query,
        .plan = malformed,
    });
    try std.testing.expect(!coverage.query_cte_structured_access);
    try std.testing.expect(!coverage.query_cte_expression_access);

    try coverage.observe(std.testing.allocator, .{
        .family = .query,
        .plan = "query:table=usage_records:ctes=1:cte0_expr_pred=2",
    });
    try std.testing.expect(coverage.query_cte_structured_access);
    try std.testing.expect(coverage.query_cte_expression_access);
}

const AppParityCorpusCoverage = sql_adapter.AppParityCorpusCoverage;

test "postgres sql adapter classifies application parity corpus" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"tenant_id":{"type":"keyword"},"organization_id":{"type":"keyword"},"cloud_instance_id":{"type":"keyword"},"user_id":{"type":"keyword"},"customer_id":{"type":"keyword"},"kind":{"type":"keyword"},"status":{"type":"keyword","default":"active"},"metric_type":{"type":"keyword"},"email":{"type":"keyword"},"name":{"type":"keyword"},"rating_status":{"type":"keyword"},"product_family":{"type":"keyword"},"enabled":{"type":"boolean"},"amount":{"type":"numeric"},"quantity":{"type":"numeric"},"rated_quantity":{"type":"numeric"},"priority":{"type":"numeric"},"created_at":{"type":"numeric"},"updated_at_ns":{"type":"numeric"},"recorded_at":{"type":"numeric"},"expires_at":{"type":"numeric"},"billing_cycle_start":{"type":"numeric"},"bucket_start":{"type":"numeric"},"metadata":{"type":"json"},"tags":{"type":"array","items":{"type":"keyword"}}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"u1\",\"tenant_id\":\"t1\",\"status\":\"queued\",\"quantity\":1,\"amount\":5,\"priority\":1,\"updated_at_ns\":1,\"metadata\":{}}",
        .version = 7,
    };
    const txn_id = [_]u8{ 0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f };
    const row_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "parity-worker",
        .txn_id = txn_id,
    };

    var external_source = try sql_adapter.parseAppParityExternalSourceCorpusAlloc(alloc);
    defer external_source.deinit(alloc);
    const corpus = external_source.root.entries;
    var required_coverage = try sql_adapter.parseAppParityCoverageRequirementsAlloc(alloc);
    defer required_coverage.deinit(alloc);

    try maybeCheckOrPromoteAppParityFixture(alloc, schema_json, external_source.source_sha256, corpus);

    var coverage = AppParityCorpusCoverage{};
    for (corpus) |entry| {
        errdefer std.debug.print("application parity corpus entry failed: {s}\n", .{entry.name});
        try coverage.observe(alloc, entry);
        try expectAppParityCorpusEntry(alloc, schema_json, schema, entry, resolver_ctx.resolver(), row_claim);
    }
    try sql_adapter.expectAppParityCoverageRequirements(coverage, required_coverage.root.required);
}

test "postgres sql adapter classifies fixture-backed application parity corpus" {
    const alloc = std.testing.allocator;
    const fixture_json = @embedFile("fixtures/sql_api_parity_corpus.json");
    var parsed_fixture = try std.json.parseFromSlice(std.json.Value, alloc, fixture_json, .{});
    defer parsed_fixture.deinit();

    const fixture_root = try sql_adapter.parseFixtureRootAlloc(alloc, parsed_fixture.value);
    defer sql_adapter.freeFixtureRoot(alloc, fixture_root);
    const source_json = @embedFile("fixtures/sql_api_parity_source_corpus.json");
    const source_sha256 = try sql_adapter.sourceCorpusSha256HexAlloc(alloc, source_json);
    defer alloc.free(source_sha256);
    try std.testing.expectEqualStrings(source_sha256, fixture_root.source_sha256);
    const skipped_entries = fixture_root.skipped_entries;
    const schema_json = fixture_root.schema_json;
    try std.testing.expectEqual(@as(usize, 0), skipped_entries.len);

    var parsed_schema = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed_schema.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_schema);
    defer runtime_schema.freeSchema(alloc, schema);

    var resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"u1\",\"tenant_id\":\"t1\",\"status\":\"queued\",\"quantity\":1,\"amount\":5,\"priority\":1,\"updated_at_ns\":1,\"metadata\":{}}",
        .version = 7,
    };
    const txn_id = [_]u8{ 0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f };
    const row_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "fixture-parity-worker",
        .txn_id = txn_id,
    };
    var seen_names = std.StringHashMapUnmanaged(void){};
    defer seen_names.deinit(alloc);
    var seen_skipped_names = std.StringHashMapUnmanaged(void){};
    defer seen_skipped_names.deinit(alloc);
    var required_coverage = try sql_adapter.parseAppParityCoverageRequirementsAlloc(alloc);
    defer required_coverage.deinit(alloc);
    for (skipped_entries) |name| {
        if (name.len == 0 or seen_skipped_names.contains(name)) return error.TestUnexpectedResult;
        try seen_skipped_names.put(alloc, name, {});
    }
    var coverage = AppParityCorpusCoverage{};

    for (fixture_root.entries) |entry_value| {
        const entry = try sql_adapter.parseFixtureEntryAlloc(alloc, entry_value);
        defer sql_adapter.freeFixtureEntry(alloc, entry);
        errdefer std.debug.print("fixture parity corpus entry failed: {s}\n", .{entry.name});
        if (seen_skipped_names.contains(entry.name)) return error.TestUnexpectedResult;
        try validateAppParityFixtureMetadataWithBaseSchema(entry, schema_json, &seen_names, alloc);
        try coverage.observe(alloc, entry);
        try expectAppParityCorpusEntry(alloc, schema_json, schema, entry, resolver_ctx.resolver(), row_claim);
    }
    try sql_adapter.expectAppParityCoverageRequirements(coverage, required_coverage.root.required);
}

test "postgres sql adapter lowers joined mutation source with separate target and source schemas" {
    const alloc = std.testing.allocator;
    const target_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"source_id":{"type":"keyword"},"status":{"type":"keyword","default":"active"},"quantity":{"type":"numeric"},"enabled":{"type":"boolean"},"metadata":{"type":"json"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const source_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"source_pk":{"type":"keyword"},"id":{"type":"keyword"},"source_status":{"type":"keyword"},"source_quantity":{"type":"numeric"},"source_enabled":{"type":"boolean"}},"required":["source_pk"],"additionalProperties":false}}},"primary_key":{"columns":["source_pk"]}}
    ;
    var parsed_target = try schema_api.parseValidatedTableSchema(alloc, target_schema_json);
    defer parsed_target.deinit(alloc);
    const target_schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_target);
    defer runtime_schema.freeSchema(alloc, target_schema);
    var parsed_source = try schema_api.parseValidatedTableSchema(alloc, source_schema_json);
    defer parsed_source.deinit(alloc);
    const source_schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_source);
    defer runtime_schema.freeSchema(alloc, source_schema);

    const txn_id = [_]u8{ 0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f };
    const row_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "joined-worker",
        .txn_id = txn_id,
    };
    const sql = "UPDATE usage_records SET quantity = source.source_quantity, status = 'synced' FROM source_records AS source WHERE usage_records.source_id = source.source_pk AND source.source_status = 'ready' FOR UPDATE SKIP LOCKED RETURNING id, quantity";

    try std.testing.expectError(error.InvalidSqlCatalog, lowerUpdateJoinedMutationSourceAlloc(
        alloc,
        sql,
        target_schema,
        &.{},
        row_claim,
    ));

    var lowered = try lowerUpdateJoinedMutationSourceWithSchemasAlloc(
        alloc,
        sql,
        target_schema,
        source_schema,
        &.{},
        row_claim,
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.target_table_name);
    try std.testing.expectEqualStrings("source_records", lowered.source_table_name);
    try std.testing.expectEqualStrings("source_records", lowered.mutation.req.source_table);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.join.on.len);
    try std.testing.expectEqualStrings("source_id", lowered.mutation.req.join.on[0].left_field);
    try std.testing.expectEqualStrings("source_pk", lowered.mutation.req.join.on[0].right_field);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.join.right.predicates.len);
    try std.testing.expectEqualStrings("source_status", lowered.mutation.req.join.right.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.source_assignments.len);
    try std.testing.expectEqualStrings("source_quantity", lowered.mutation.req.source_assignments[0].source_field);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.operations.len);
    try std.testing.expectEqual(@as(usize, 2), lowered.mutation.req.returning.len);

    var cte_update = try lowerUpdateJoinedMutationSourceWithSchemasAlloc(
        alloc,
        "WITH ready_sources AS (SELECT source_pk, source_status FROM source_records WHERE source_status = 'ready') UPDATE usage_records SET status = source.source_status FROM ready_sources AS source WHERE usage_records.source_id = source.source_pk FOR UPDATE RETURNING id",
        target_schema,
        source_schema,
        &.{},
        row_claim,
    );
    defer cte_update.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", cte_update.target_table_name);
    try std.testing.expectEqualStrings("source_records", cte_update.source_table_name);
    try std.testing.expectEqualStrings("source_records", cte_update.mutation.req.source_table);
    try std.testing.expectEqual(@as(usize, 1), cte_update.mutation.req.ctes.len);
    try std.testing.expectEqualStrings("ready_sources", cte_update.mutation.req.ctes[0].name);
    try std.testing.expectEqual(@as(usize, 1), cte_update.mutation.req.ctes[0].query.predicates.len);
    try std.testing.expectEqualStrings("source_status", cte_update.mutation.req.ctes[0].query.predicates[0].field);
    try std.testing.expectEqualStrings("ready_sources", cte_update.mutation.req.join.right.source_cte);
    try std.testing.expectEqual(@as(usize, 1), cte_update.mutation.req.join.on.len);
    try std.testing.expectEqualStrings("source_pk", cte_update.mutation.req.join.on[0].right_field);
    try std.testing.expectEqual(@as(usize, 1), cte_update.mutation.req.source_assignments.len);
    try std.testing.expectEqualStrings("source_status", cte_update.mutation.req.source_assignments[0].source_field);
    try std.testing.expectEqual(@as(usize, 1), cte_update.mutation.req.returning.len);

    var cte_delete = try lowerDeleteJoinedMutationSourceWithSchemasAlloc(
        alloc,
        "WITH stale_sources AS (SELECT source_pk FROM source_records WHERE source_status = 'stale') DELETE FROM usage_records USING stale_sources AS source WHERE usage_records.source_id = source.source_pk FOR UPDATE RETURNING id",
        target_schema,
        source_schema,
        &.{},
        row_claim,
    );
    defer cte_delete.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", cte_delete.target_table_name);
    try std.testing.expectEqualStrings("source_records", cte_delete.source_table_name);
    try std.testing.expectEqualStrings("source_records", cte_delete.mutation.req.source_table);
