            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.json_set_expressions.len);
            try std.testing.expectEqualStrings("metadata", update_source.mutation.req.json_set_expressions[0].field);
            try std.testing.expectEqualStrings("billing", update_source.mutation.req.json_set_expressions[0].path[0]);
            try std.testing.expectEqualStrings("status_key", update_source.mutation.req.json_set_expressions[0].path[1]);

            var result = try db.mutateRelationalRowsFromSource(alloc, schema, update_source.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), result.matched);
            try std.testing.expectEqual(@as(u32, 1), result.staged);
            try std.testing.expectEqual(@as(usize, 1), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"u1\",\"metadata.billing.status_key\":\"queued\"}", result.returning_rows[0]);
        },
        else => return error.TestUnexpectedResult,
    }

    try db.commitTransaction(txn_id, 4_010);
    committed = true;

    const select = [_][]const u8{ "id", "metadata.billing.status_key" };
    const predicates = [_]runtime_schema.RelationalCheck{
        .{ .name = "", .field = "id", .op = .eq, .value_json = "\"u1\"" },
    };
    var rows = try db.queryRelationalRows(alloc, schema, .{
        .select = select[0..],
        .predicates = predicates[0..],
    });
    defer rows.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 1), rows.total);
    try std.testing.expectEqual(@as(usize, 1), rows.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"u1\",\"metadata\":{\"billing\":{\"status_key\":\"queued\"}}}", rows.rows[0]);

    var untouched = (try db.lookup(alloc, "row:u2", .{})).?;
    defer untouched.deinit(alloc);
    try std.testing.expect(std.mem.indexOf(u8, untouched.json, "status_key") == null);
}

test "postgres sql adapter mutation source expression transforms execute through relational storage" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"organization_id":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-mutation-source-expression-transforms", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:u1", .value = "{\"id\":\"u1\",\"status\":\"QUEUED\",\"amount\":2,\"organization_id\":\"o1\"}" },
            .{ .key = "row:u2", .value = "{\"id\":\"u2\",\"status\":\"READY\",\"amount\":4,\"organization_id\":\"o1\"}" },
            .{ .key = "row:u3", .value = "{\"id\":\"u3\",\"status\":\"SKIP\",\"amount\":8,\"organization_id\":\"o2\"}" },
        },
        .sync_level = .write,
    });

    const txn_id = try db.beginTransaction(4_101);
    var committed = false;
    defer if (!committed) db.abortTransaction(txn_id, 4_102) catch {};
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-expression-update",
        .txn_id = txn_id,
    };

    var plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = lower(status) || ':' || id, amount = amount + coalesce(amount, 1) WHERE organization_id = 'o1' ORDER BY id ASC FOR UPDATE RETURNING id, status, amount, lower(status) AS status_key",
        schema,
        &.{},
        .{ .row_claim = claim },
    );
    defer plan.deinit(alloc);

    switch (plan) {
        .update_source => |update_source| {
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.patch_expressions.len);
            try std.testing.expectEqualStrings("status", update_source.mutation.req.patch_expressions[0].field);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.increment_expressions.len);
            try std.testing.expectEqualStrings("amount", update_source.mutation.req.increment_expressions[0].field);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.returning_expressions.len);

            var result = try db.mutateRelationalRowsFromSource(alloc, schema, update_source.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 2), result.matched);
            try std.testing.expectEqual(@as(u32, 2), result.staged);
            try std.testing.expectEqual(@as(usize, 2), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"queued:u1\",\"amount\":4,\"status_key\":\"queued:u1\"}", result.returning_rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"ready:u2\",\"amount\":8,\"status_key\":\"ready:u2\"}", result.returning_rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    try db.commitTransaction(txn_id, 4_110);
    committed = true;

    const select = [_][]const u8{ "id", "status", "amount" };
    const order_by = [_]db_mod.types.RelationalRowsQueryOrder{.{
        .field = "id",
        .direction = .asc,
    }};
    var rows = try db.queryRelationalRows(alloc, schema, .{
        .select = select[0..],
        .order_by = order_by[0..],
    });
    defer rows.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 3), rows.total);
    try std.testing.expectEqual(@as(usize, 3), rows.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"queued:u1\",\"amount\":4}", rows.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"ready:u2\",\"amount\":8}", rows.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"u3\",\"status\":\"SKIP\",\"amount\":8}", rows.rows[2]);

    const text_txn_id = try db.beginTransaction(4_201);
    var text_committed = false;
    defer if (!text_committed) db.abortTransaction(text_txn_id, 4_202) catch {};
    const text_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-expression-text-update",
        .txn_id = text_txn_id,
    };

    var text_plan = try lowerWritePlanAlloc(
        alloc,
        "UPDATE usage_records SET status = split_part(status, ':', 1) || '-done', amount = regexp_count(status, '[a-z]+') + position(':' in status) WHERE organization_id = 'o1' ORDER BY id ASC FOR UPDATE RETURNING id, status, amount, split_part(status, '-', 1) AS status_prefix",
        schema,
        &.{},
        .{ .row_claim = text_claim },
    );
    defer text_plan.deinit(alloc);

    switch (text_plan) {
        .update_source => |update_source| {
            try std.testing.expectEqual(@as(usize, 2), update_source.mutation.req.patch_expressions.len);
            try std.testing.expectEqualStrings("status", update_source.mutation.req.patch_expressions[0].field);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.concat, update_source.mutation.req.patch_expressions[0].expression.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.split_part, update_source.mutation.req.patch_expressions[0].expression.operands[0].kind);
            try std.testing.expectEqualStrings("amount", update_source.mutation.req.patch_expressions[1].field);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, update_source.mutation.req.patch_expressions[1].expression.kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.regexp_count, update_source.mutation.req.patch_expressions[1].expression.operands[0].kind);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.strpos, update_source.mutation.req.patch_expressions[1].expression.operands[1].kind);
            try std.testing.expectEqual(@as(usize, 1), update_source.mutation.req.returning_expressions.len);
            try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.split_part, update_source.mutation.req.returning_expressions[0].expression.kind);

            var result = try db.mutateRelationalRowsFromSource(alloc, schema, update_source.mutation.req);
            defer result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 2), result.matched);
            try std.testing.expectEqual(@as(u32, 2), result.staged);
            try std.testing.expectEqual(@as(usize, 2), result.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"queued-done\",\"amount\":9,\"status_prefix\":\"queued\"}", result.returning_rows[0]);
            try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"ready-done\",\"amount\":8,\"status_prefix\":\"ready\"}", result.returning_rows[1]);
        },
        else => return error.TestUnexpectedResult,
    }

    try db.commitTransaction(text_txn_id, 4_210);
    text_committed = true;

    var text_rows = try db.queryRelationalRows(alloc, schema, .{
        .select = select[0..],
        .order_by = order_by[0..],
    });
    defer text_rows.deinit(alloc);

    try std.testing.expectEqual(@as(u32, 3), text_rows.total);
    try std.testing.expectEqual(@as(usize, 3), text_rows.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"u1\",\"status\":\"queued-done\",\"amount\":9}", text_rows.rows[0]);
    try std.testing.expectEqualStrings("{\"id\":\"u2\",\"status\":\"ready-done\",\"amount\":8}", text_rows.rows[1]);
    try std.testing.expectEqualStrings("{\"id\":\"u3\",\"status\":\"SKIP\",\"amount\":8}", text_rows.rows[2]);
}

test "postgres sql adapter insert source unique conflict executes through relational storage" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"source_id":{"type":"keyword"},"target_source_id":{"type":"keyword"},"status":{"type":"keyword","default":"active"}},"required":["id","source_id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"unique_constraints":[{"name":"usage_records_source_id_key","columns":["source_id"]}]}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-insert-source-unique-conflict", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:existing", .value = "{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"old\"}" },
            .{ .key = "row:source", .value = "{\"id\":\"source\",\"source_id\":\"source:input\",\"target_source_id\":\"source:1\",\"status\":\"new\"}" },
            .{ .key = "row:source_default", .value = "{\"id\":\"source_default\",\"source_id\":\"source:input:default\",\"target_source_id\":\"source:1\",\"status\":\"ignored\"}" },
            .{ .key = "row:source_guard", .value = "{\"id\":\"source_guard\",\"source_id\":\"source:input:guard\",\"target_source_id\":\"source:1\",\"status\":\"guarded\"}" },
            .{ .key = "row:source_nothing", .value = "{\"id\":\"source_nothing\",\"source_id\":\"source:input:2\",\"target_source_id\":\"source:1\",\"status\":\"ignored\"}" },
        },
        .sync_level = .write,
    });

    const existing_version = try db.getTimestamp(alloc, "row:existing");
    var resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"old\"}",
        .version = existing_version,
        .resolved_key = "row:existing",
    };
    var plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, source_id, status) SELECT id || '_copy' AS id, target_source_id AS source_id, upper(status) AS status FROM usage_records WHERE id = 'source' ON CONFLICT (source_id) DO UPDATE SET status = excluded.status RETURNING id, source_id, status",
        schema,
        &.{},
        .{ .unique_resolver = resolver_ctx.resolver() },
    );
    defer plan.deinit(alloc);

    switch (plan) {
        .insert_source => |insert_source| {
            const conflict = insert_source.insert_source.req.on_conflict orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictTargetKind.unique, conflict.target.kind);
            try std.testing.expectEqualStrings("usage_records_source_id_key", conflict.target.unique_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictAction.update, conflict.action);

            var source_result = try db.queryRelationalRows(alloc, schema, insert_source.insert_source.req.source);
            defer source_result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), source_result.total);
            try std.testing.expectEqual(@as(usize, 1), source_result.rows.len);

            var batch = try relational_rows.buildRowsInsertSourceBatchAlloc(
                alloc,
                insert_source.table_name,
                schema,
                insert_source.insert_source.req,
                source_result.rows,
                resolver_ctx.resolver(),
            );
            defer batch.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 0), batch.inserted);
            try std.testing.expectEqual(@as(u32, 1), batch.transformed);
            try std.testing.expectEqual(@as(usize, 1), batch.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"NEW\"}", batch.returning_rows[0]);
            try db.batch(batch.req);
        },
        else => return error.TestUnexpectedResult,
    }

    const existing_after_update_version = try db.getTimestamp(alloc, "row:existing");
    var default_resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"NEW\"}",
        .version = existing_after_update_version,
        .resolved_key = "row:existing",
    };
    var default_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, source_id, status) SELECT id || '_copy' AS id, target_source_id AS source_id, upper(status) AS status FROM usage_records WHERE id = 'source_default' ON CONFLICT (source_id) DO UPDATE SET status = DEFAULT RETURNING id, source_id, status",
        schema,
        &.{},
        .{ .unique_resolver = default_resolver_ctx.resolver() },
    );
    defer default_plan.deinit(alloc);

    switch (default_plan) {
        .insert_source => |insert_source| {
            const conflict = insert_source.insert_source.req.on_conflict orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictAction.update, conflict.action);
            try std.testing.expectEqual(@as(usize, 1), conflict.operations.len);
            try std.testing.expectEqualStrings("status", conflict.operations[0].path);
            try std.testing.expectEqualStrings("\"active\"", conflict.operations[0].value_json.?);

            var source_result = try db.queryRelationalRows(alloc, schema, insert_source.insert_source.req.source);
            defer source_result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), source_result.total);
            try std.testing.expectEqual(@as(usize, 1), source_result.rows.len);

            var batch = try relational_rows.buildRowsInsertSourceBatchAlloc(
                alloc,
                insert_source.table_name,
                schema,
                insert_source.insert_source.req,
                source_result.rows,
                default_resolver_ctx.resolver(),
            );
            defer batch.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 0), batch.inserted);
            try std.testing.expectEqual(@as(u32, 1), batch.transformed);
            try std.testing.expectEqual(@as(usize, 1), batch.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"active\"}", batch.returning_rows[0]);
            try db.batch(batch.req);
        },
        else => return error.TestUnexpectedResult,
    }

    const existing_after_default_version = try db.getTimestamp(alloc, "row:existing");
    var guarded_resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"active\"}",
        .version = existing_after_default_version,
        .resolved_key = "row:existing",
    };
    var guarded_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, source_id, status) SELECT id || '_copy' AS id, target_source_id AS source_id, upper(status) AS status FROM usage_records WHERE id = 'source_guard' ON CONFLICT (source_id) DO UPDATE SET status = excluded.status WHERE excluded.status = status RETURNING id, source_id, status",
        schema,
        &.{},
        .{ .unique_resolver = guarded_resolver_ctx.resolver() },
    );
    defer guarded_plan.deinit(alloc);

    switch (guarded_plan) {
        .insert_source => |insert_source| {
            const conflict = insert_source.insert_source.req.on_conflict orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictTargetKind.unique, conflict.target.kind);
            try std.testing.expectEqualStrings("usage_records_source_id_key", conflict.target.unique_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictAction.update, conflict.action);
            try std.testing.expect(conflict.where_expression != null);

            var source_result = try db.queryRelationalRows(alloc, schema, insert_source.insert_source.req.source);
            defer source_result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), source_result.total);
            try std.testing.expectEqual(@as(usize, 1), source_result.rows.len);

            var batch = try relational_rows.buildRowsInsertSourceBatchAlloc(
                alloc,
                insert_source.table_name,
                schema,
                insert_source.insert_source.req,
                source_result.rows,
                guarded_resolver_ctx.resolver(),
            );
            defer batch.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 0), batch.inserted);
            try std.testing.expectEqual(@as(u32, 0), batch.transformed);
            try std.testing.expectEqual(@as(usize, 0), batch.returning_rows.len);
            try db.batch(batch.req);
        },
        else => return error.TestUnexpectedResult,
    }

    const existing_after_guard_version = try db.getTimestamp(alloc, "row:existing");
    var do_nothing_resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"active\"}",
        .version = existing_after_guard_version,
        .resolved_key = "row:existing",
    };
    var do_nothing_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, source_id, status) SELECT id || '_copy' AS id, target_source_id AS source_id, upper(status) AS status FROM usage_records WHERE id = 'source_nothing' ON CONFLICT (source_id) DO NOTHING RETURNING id, source_id, status",
        schema,
        &.{},
        .{ .unique_resolver = do_nothing_resolver_ctx.resolver() },
    );
    defer do_nothing_plan.deinit(alloc);

    switch (do_nothing_plan) {
        .insert_source => |insert_source| {
            const conflict = insert_source.insert_source.req.on_conflict orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictTargetKind.unique, conflict.target.kind);
            try std.testing.expectEqualStrings("usage_records_source_id_key", conflict.target.unique_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictAction.nothing, conflict.action);

            var source_result = try db.queryRelationalRows(alloc, schema, insert_source.insert_source.req.source);
            defer source_result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), source_result.total);
            try std.testing.expectEqual(@as(usize, 1), source_result.rows.len);

            var batch = try relational_rows.buildRowsInsertSourceBatchAlloc(
                alloc,
                insert_source.table_name,
                schema,
                insert_source.insert_source.req,
                source_result.rows,
                do_nothing_resolver_ctx.resolver(),
            );
            defer batch.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 0), batch.inserted);
            try std.testing.expectEqual(@as(u32, 0), batch.transformed);
            try std.testing.expectEqual(@as(usize, 0), batch.returning_rows.len);
            try db.batch(batch.req);
        },
        else => return error.TestUnexpectedResult,
    }

    const select = [_][]const u8{ "id", "source_id", "status" };
    var rows = try db.queryRelationalRows(alloc, schema, .{
        .select = select[0..],
        .predicates = &.{.{
            .name = "",
            .field = "id",
            .op = .eq,
            .value_json = "\"existing\"",
        }},
    });
    defer rows.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), rows.total);
    try std.testing.expectEqual(@as(usize, 1), rows.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"existing\",\"source_id\":\"source:1\",\"status\":\"active\"}", rows.rows[0]);
}

test "postgres sql adapter insert source temporal unique conflict executes through relational storage" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"sku":{"type":"keyword"},"target_sku":{"type":"keyword"},"valid_from":{"type":"numeric"},"valid_to":{"type":"numeric"},"price":{"type":"numeric"}},"required":["id","sku","valid_from","valid_to"],"additionalProperties":false}}},"primary_key":{"columns":["id"]},"periods":[{"name":"valid_time","start_column":"valid_from","end_column":"valid_to"}],"unique_constraints":[{"name":"prices_sku_time_key","columns":["sku"],"without_overlaps_period":"valid_time"}]}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var tmp = std.testing.tmpDir(.{});
    defer tmp.cleanup();

    const path = try std.fmt.allocPrint(alloc, ".zig-cache/tmp/{s}/sql-insert-source-temporal-unique-conflict", .{tmp.sub_path});
    defer alloc.free(path);

    var db = try db_mod.DB.open(alloc, path, .{});
    defer db.close();
    try db.applyTableSchemaJson(alloc, schema_json, .{});

    try db.batch(.{
        .writes = &.{
            .{ .key = "row:existing", .value = "{\"id\":\"existing\",\"sku\":\"sku:a\",\"valid_from\":0,\"valid_to\":10,\"price\":10}" },
            .{ .key = "row:source", .value = "{\"id\":\"source\",\"sku\":\"sku:source\",\"target_sku\":\"sku:a\",\"valid_from\":5,\"valid_to\":15,\"price\":12}" },
        },
        .sync_level = .write,
    });

    const existing_version = try db.getTimestamp(alloc, "row:existing");
    var resolver_ctx = TestPrimaryResolver{
        .row_json = "{\"id\":\"existing\",\"sku\":\"sku:a\",\"valid_from\":0,\"valid_to\":10,\"price\":10}",
        .version = existing_version,
        .resolved_key = "row:existing",
    };
    var plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO prices (id, sku, valid_from, valid_to, price) SELECT id || '_copy' AS id, target_sku AS sku, valid_from, valid_to, price + 1 AS price FROM prices WHERE id = 'source' ON CONFLICT ON CONSTRAINT prices_sku_time_key DO UPDATE SET price = excluded.price RETURNING id, sku, valid_from, valid_to, price",
        schema,
        &.{},
        .{ .unique_resolver = resolver_ctx.resolver() },
    );
    defer plan.deinit(alloc);

    switch (plan) {
        .insert_source => |insert_source| {
            const conflict = insert_source.insert_source.req.on_conflict orelse return error.TestUnexpectedResult;
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictTargetKind.unique, conflict.target.kind);
            try std.testing.expectEqualStrings("prices_sku_time_key", conflict.target.unique_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsConflictAction.update, conflict.action);

            var source_result = try db.queryRelationalRows(alloc, schema, insert_source.insert_source.req.source);
            defer source_result.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 1), source_result.total);
            try std.testing.expectEqual(@as(usize, 1), source_result.rows.len);

            var batch = try relational_rows.buildRowsInsertSourceBatchAlloc(
                alloc,
                insert_source.table_name,
                schema,
                insert_source.insert_source.req,
                source_result.rows,
                resolver_ctx.resolver(),
            );
            defer batch.deinit(alloc);
            try std.testing.expectEqual(@as(u32, 0), batch.inserted);
            try std.testing.expectEqual(@as(u32, 1), batch.transformed);
            try std.testing.expectEqual(@as(usize, 1), batch.returning_rows.len);
            try std.testing.expectEqualStrings("{\"id\":\"existing\",\"sku\":\"sku:a\",\"valid_from\":0,\"valid_to\":10,\"price\":13}", batch.returning_rows[0]);
            try db.batch(batch.req);
        },
        else => return error.TestUnexpectedResult,
    }

    const select = [_][]const u8{ "id", "sku", "valid_from", "valid_to", "price" };
    var rows = try db.queryRelationalRows(alloc, schema, .{
        .select = select[0..],
        .predicates = &.{.{
            .name = "",
            .field = "id",
            .op = .eq,
            .value_json = "\"existing\"",
        }},
    });
    defer rows.deinit(alloc);
    try std.testing.expectEqual(@as(u32, 1), rows.total);
    try std.testing.expectEqual(@as(usize, 1), rows.rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"existing\",\"sku\":\"sku:a\",\"valid_from\":0,\"valid_to\":10,\"price\":13}", rows.rows[0]);
}

test "postgres sql adapter write plan honors renamed primary conflict constraints" {
    const alloc = std.testing.allocator;
    const setup_schema_json = try schemaJsonFromSetupSqlAlloc(alloc, &.{
        "CREATE TABLE usage_records (id uuid PRIMARY KEY, status text);",
        "ALTER TABLE usage_records RENAME CONSTRAINT usage_records_pkey TO usage_records_id_pk;",
    });
    defer alloc.free(setup_schema_json);
    var parsed_setup = try schema_api.parseValidatedTableSchema(alloc, setup_schema_json);
    defer parsed_setup.deinit(alloc);
    const setup_schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed_setup);
    defer runtime_schema.freeSchema(alloc, setup_schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"existing\"}", .version = 12 };

    var custom_named_write_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ($1, $2) ON CONFLICT ON CONSTRAINT usage_records_id_pk DO NOTHING RETURNING *",
        setup_schema,
        &.{ .{ .string = "u1" }, .{ .string = "pending" } },
        .{ .unique_resolver = resolver_ctx.resolver() },
    );
    defer custom_named_write_plan.deinit(alloc);
    switch (custom_named_write_plan) {
        .insert => |insert| {
            try std.testing.expectEqual(@as(u32, 0), insert.batch.inserted);
            try std.testing.expectEqual(@as(usize, 0), insert.batch.writes.len);
            try std.testing.expectEqual(@as(usize, 0), insert.batch.returning_rows.len);
        },
        else => return error.TestUnexpectedResult,
    }

    var custom_named_update_plan = try lowerWritePlanAlloc(
        alloc,
        "INSERT INTO usage_records (id, status) VALUES ($1, $2) ON CONFLICT ON CONSTRAINT usage_records_id_pk DO UPDATE SET status = excluded.status RETURNING id, status",
        setup_schema,
        &.{ .{ .string = "u1" }, .{ .string = "pending" } },
        .{ .unique_resolver = resolver_ctx.resolver() },
    );
    defer custom_named_update_plan.deinit(alloc);
    switch (custom_named_update_plan) {
        .insert => |insert| {
            try std.testing.expectEqual(@as(u32, 0), insert.batch.inserted);
            try std.testing.expectEqual(@as(usize, 0), insert.batch.writes.len);
            try std.testing.expectEqual(@as(usize, 1), insert.batch.transforms.len);
            try std.testing.expectEqual(@as(usize, 1), insert.batch.returning_rows.len);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter lowers non recursive cte query plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"amount":{"type":"numeric"},"created_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerQueryPlanAlloc(
        alloc,
        "WITH open_orders AS (SELECT id, status, amount, created_at FROM orders WHERE status = 'open'), expensive_open_orders AS (SELECT id, amount, created_at FROM open_orders WHERE amount > 10) SELECT id FROM expensive_open_orders ORDER BY created_at DESC LIMIT 2",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("orders", lowered.table_name);
    try std.testing.expectEqual(@as(usize, 2), lowered.plan.ctes.len);
    try std.testing.expectEqualStrings("open_orders", lowered.plan.ctes[0].name);
    try std.testing.expectEqualStrings("", lowered.plan.ctes[0].query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes[0].query.predicates.len);
    try std.testing.expectEqualStrings("status", lowered.plan.ctes[0].query.predicates[0].field);
    try std.testing.expectEqualStrings("\"open\"", lowered.plan.ctes[0].query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("expensive_open_orders", lowered.plan.ctes[1].name);
    try std.testing.expectEqualStrings("open_orders", lowered.plan.ctes[1].query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.ctes[1].query.predicates.len);
    try std.testing.expectEqualStrings("amount", lowered.plan.ctes[1].query.predicates[0].field);
    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.gt, lowered.plan.ctes[1].query.predicates[0].op);
    try std.testing.expectEqualStrings("10", lowered.plan.ctes[1].query.predicates[0].value_json.?);
    try std.testing.expectEqualStrings("expensive_open_orders", lowered.plan.query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.select.len);
    try std.testing.expectEqualStrings("id", lowered.plan.query.select[0]);
    try std.testing.expectEqual(@as(usize, 1), lowered.plan.query.order_by.len);
    try std.testing.expectEqualStrings("created_at", lowered.plan.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 2), lowered.plan.query.limit.?);

    var direct_select = try lowerSelectAlloc(
        alloc,
        "WITH open_orders AS (SELECT id, status, created_at FROM orders WHERE status = 'open') SELECT id FROM open_orders ORDER BY created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer direct_select.deinit(alloc);
    try std.testing.expectEqualStrings("orders", direct_select.table_name);
    try std.testing.expectEqual(@as(usize, 1), direct_select.ctes.len);
    try std.testing.expectEqualStrings("open_orders", direct_select.ctes[0].name);
    try std.testing.expectEqual(@as(usize, 1), direct_select.ctes[0].query.predicates.len);
    try std.testing.expectEqualStrings("status", direct_select.ctes[0].query.predicates[0].field);
    try std.testing.expectEqualStrings("open_orders", direct_select.query.source_cte);
    try std.testing.expectEqual(@as(usize, 1), direct_select.query.select.len);
    try std.testing.expectEqualStrings("id", direct_select.query.select[0]);
    try std.testing.expectEqual(@as(usize, 1), direct_select.query.order_by.len);
    try std.testing.expectEqualStrings("created_at", direct_select.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 5), direct_select.query.limit.?);

    var column_alias_list = try lowerSelectAlloc(
        alloc,
        "WITH open_orders(order_id, order_status, order_created_at) AS (SELECT id, status, created_at FROM orders WHERE status = 'open') SELECT order_id FROM open_orders ORDER BY order_created_at DESC LIMIT 5",
        schema,
        &.{},
    );
    defer column_alias_list.deinit(alloc);
    try std.testing.expectEqualStrings("orders", column_alias_list.table_name);
    try std.testing.expectEqual(@as(usize, 1), column_alias_list.ctes.len);
    try std.testing.expectEqualStrings("open_orders", column_alias_list.ctes[0].name);
    try std.testing.expectEqual(@as(usize, 0), column_alias_list.ctes[0].query.select.len);
    try std.testing.expectEqual(@as(usize, 3), column_alias_list.ctes[0].query.field_aliases.len);
    try std.testing.expectEqualStrings("order_id", column_alias_list.ctes[0].query.field_aliases[0].output);
    try std.testing.expectEqualStrings("id", column_alias_list.ctes[0].query.field_aliases[0].field);
    try std.testing.expectEqualStrings("order_status", column_alias_list.ctes[0].query.field_aliases[1].output);
    try std.testing.expectEqualStrings("status", column_alias_list.ctes[0].query.field_aliases[1].field);
    try std.testing.expectEqualStrings("order_created_at", column_alias_list.ctes[0].query.field_aliases[2].output);
    try std.testing.expectEqualStrings("created_at", column_alias_list.ctes[0].query.field_aliases[2].field);
    try std.testing.expectEqualStrings("open_orders", column_alias_list.query.source_cte);
    try std.testing.expectEqualStrings("order_id", column_alias_list.query.select[0]);
    try std.testing.expectEqualStrings("order_created_at", column_alias_list.query.order_by[0].field);

    var expression_alias_list = try lowerQueryPlanAlloc(
        alloc,
        "WITH normalized_orders(order_id, status_key) AS (SELECT id, lower(status) FROM orders WHERE amount > 0) SELECT order_id FROM normalized_orders WHERE status_key = 'open'",
        schema,
        &.{},
    );
    defer expression_alias_list.deinit(alloc);
    try std.testing.expectEqualStrings("orders", expression_alias_list.table_name);
    try std.testing.expectEqual(@as(usize, 1), expression_alias_list.plan.ctes.len);
    try std.testing.expectEqual(@as(usize, 1), expression_alias_list.plan.ctes[0].query.field_aliases.len);
    try std.testing.expectEqualStrings("order_id", expression_alias_list.plan.ctes[0].query.field_aliases[0].output);
    try std.testing.expectEqualStrings("id", expression_alias_list.plan.ctes[0].query.field_aliases[0].field);
    try std.testing.expectEqual(@as(usize, 1), expression_alias_list.plan.ctes[0].query.expressions.len);
    try std.testing.expectEqualStrings("status_key", expression_alias_list.plan.ctes[0].query.expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, expression_alias_list.plan.ctes[0].query.expressions[0].expression.kind);
    try std.testing.expectEqualStrings("normalized_orders", expression_alias_list.plan.query.source_cte);
    try std.testing.expectEqualStrings("order_id", expression_alias_list.plan.query.select[0]);
    try std.testing.expectEqualStrings("status_key", expression_alias_list.plan.query.predicates[0].field);

    var hinted = try lowerQueryPlanAlloc(
        alloc,
        "WITH open_orders AS MATERIALIZED (SELECT id, status, created_at FROM orders WHERE status = 'open'), ordered_orders AS NOT MATERIALIZED (SELECT id, created_at FROM open_orders WHERE created_at > 0) SELECT id FROM ordered_orders ORDER BY created_at DESC LIMIT 3",
        schema,
        &.{},
    );
    defer hinted.deinit(alloc);
    try std.testing.expectEqualStrings("orders", hinted.table_name);
    try std.testing.expectEqual(@as(usize, 2), hinted.plan.ctes.len);
    try std.testing.expectEqualStrings("open_orders", hinted.plan.ctes[0].name);
    try std.testing.expectEqualStrings("ordered_orders", hinted.plan.ctes[1].name);
    try std.testing.expectEqualStrings("open_orders", hinted.plan.ctes[1].query.source_cte);
    try std.testing.expectEqualStrings("ordered_orders", hinted.plan.query.source_cte);
    try std.testing.expectEqual(@as(u32, 3), hinted.plan.query.limit.?);

    var plain = try lowerQueryPlanAlloc(
        alloc,
        "SELECT id FROM orders WHERE status = 'open'",
        schema,
        &.{},
    );
    defer plain.deinit(alloc);
    try std.testing.expectEqualStrings("orders", plain.table_name);
    try std.testing.expectEqual(@as(usize, 0), plain.plan.ctes.len);
    try std.testing.expectEqual(@as(usize, 1), plain.plan.query.predicates.len);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH early AS (SELECT id FROM later), later AS (SELECT id FROM orders) SELECT id FROM early",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH open_orders(order_id) AS (SELECT id, status FROM orders) SELECT order_id FROM open_orders",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH open_orders(order_id, order_id) AS (SELECT id, status FROM orders) SELECT order_id FROM open_orders",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH open_orders(order_id) AS (SELECT * FROM orders) SELECT order_id FROM open_orders",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH ids_only AS (SELECT id FROM orders) SELECT amount FROM ids_only",
        schema,
        &.{},
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerQueryPlanAlloc(
        alloc,
        "WITH ids_only AS (SELECT id FROM orders), bad AS (SELECT amount FROM ids_only) SELECT amount FROM bad",
        schema,
        &.{},
    ));
}

test "postgres sql adapter lowers recursive cte stream contract" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"parent_id":{"type":"keyword"},"depth":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var lowered = try lowerReadPlanAlloc(
        alloc,
        "WITH RECURSIVE walk(id, depth) AS (SELECT id, depth FROM nodes WHERE parent_id = 'root' UNION ALL SELECT nodes.id, walk.depth + 1 FROM nodes JOIN walk ON nodes.parent_id = walk.id) SELECT id FROM walk",
        schema,
        &.{},
    );
    defer lowered.deinit(alloc);

    const recursive = switch (lowered) {
        .recursive_cte => |plan| plan,
        else => return error.TestUnexpectedResult,
    };
    try std.testing.expectEqualStrings("walk", recursive.cte_name);
    try std.testing.expectEqual(SelectSetOperation.union_all, recursive.operation);
    try std.testing.expect(recursive.recursive_member_references_cte);
    const recursive_member_join = switch (recursive.recursive_member) {
        .join => |join| join,
    };
    try std.testing.expectEqualStrings("nodes", recursive_member_join.left_table_name);
    try std.testing.expectEqualStrings("walk", recursive_member_join.right_table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsJoinType.inner, recursive_member_join.join_type);
    try std.testing.expectEqual(@as(usize, 1), recursive_member_join.on.len);
    try std.testing.expectEqual(@as(usize, 2), recursive_member_join.projections.len);
    try std.testing.expectEqualStrings("id", recursive_member_join.projections[0].output);
    try std.testing.expectEqualStrings("depth", recursive_member_join.projections[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.field, recursive_member_join.projections[0].expression.kind);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionFieldSource.row, recursive_member_join.projections[0].expression.field_source);
    try std.testing.expectEqualStrings("id", recursive_member_join.projections[0].expression.field);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, recursive_member_join.projections[1].expression.kind);
    try std.testing.expectEqual(@as(usize, 2), recursive_member_join.projections[1].expression.operands.len);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionFieldSource.source, recursive_member_join.projections[1].expression.operands[0].field_source);
    try std.testing.expectEqualStrings("depth", recursive_member_join.projections[1].expression.operands[0].field);
    try std.testing.expectEqualStrings("parent_id", recursive_member_join.on[0].left_field);
    try std.testing.expectEqualStrings("id", recursive_member_join.on[0].right_field);
    try std.testing.expectEqual(@as(?u32, db_mod.types.default_relational_rows_cte_max_rows), recursive.max_rows);
    try std.testing.expectEqual(@as(?u64, db_mod.types.default_relational_rows_cte_max_bytes), recursive.max_bytes);
    try std.testing.expectEqual(@as(?u64, db_mod.types.default_relational_rows_cte_spill_after_bytes), recursive.spill_after_bytes);
    try std.testing.expectEqualStrings("nodes", recursive.anchor.table_name);
    try std.testing.expectEqual(@as(usize, 1), recursive.anchor.plan.query.predicates.len);
    try std.testing.expectEqualStrings("parent_id", recursive.anchor.plan.query.predicates[0].field);
    try std.testing.expectEqual(@as(usize, 2), recursive.output_columns.len);
    try std.testing.expectEqualStrings("id", recursive.output_columns[0].name);
    try std.testing.expectEqualStrings("depth", recursive.output_columns[1].name);

    try std.testing.expectError(error.UnsupportedSqlShape, lowerRecursiveCtePlanAlloc(
        alloc,
        "WITH RECURSIVE walk AS (SELECT id FROM nodes UNION ALL SELECT id FROM nodes) SELECT id FROM walk",
        schema,
        &.{},
        .{},
    ));
}

test "postgres sql adapter lowers recursive cte joined mutation sources" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"organization_id":{"type":"keyword"},"status":{"type":"keyword"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    const txn_id = [_]u8{ 0x60, 0x61, 0x62, 0x63, 0x64, 0x65, 0x66, 0x67, 0x68, 0x69, 0x6a, 0x6b, 0x6c, 0x6d, 0x6e, 0x6f };
    const row_claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-recursive-joined-mutation",
        .txn_id = txn_id,
    };

    var update_plan = try lowerWritePlanAlloc(
        alloc,
        "WITH RECURSIVE source_rows AS (SELECT id FROM usage_records UNION ALL SELECT child.id FROM usage_records AS child JOIN source_rows AS parent ON child.organization_id = parent.id) UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM source_rows)",
        schema,
        &.{},
        .{ .row_claim = row_claim },
    );
    defer update_plan.deinit(alloc);
    switch (update_plan) {
        .recursive_update_joined_source => |recursive_update| {
            try std.testing.expectEqualStrings("source_rows", recursive_update.recursive.cte_name);
            try std.testing.expectEqualStrings("usage_records", recursive_update.mutation.target_table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.update, recursive_update.mutation.mutation.req.kind);
            try std.testing.expect(sql_adapter.recursiveJoinedMutationSourceUsesCte(recursive_update.mutation.mutation.req, recursive_update.recursive.cte_name));
        },
        else => return error.TestUnexpectedResult,
    }

    var delete_plan = try lowerWritePlanAlloc(
        alloc,
        "WITH RECURSIVE source_rows AS (SELECT id FROM usage_records UNION ALL SELECT child.id FROM usage_records AS child JOIN source_rows AS parent ON child.organization_id = parent.id) DELETE FROM usage_records WHERE id IN (SELECT id FROM source_rows)",
        schema,
        &.{},
        .{ .row_claim = row_claim },
    );
    defer delete_plan.deinit(alloc);
    switch (delete_plan) {
        .recursive_delete_joined_source => |recursive_delete| {
            try std.testing.expectEqualStrings("source_rows", recursive_delete.recursive.cte_name);
            try std.testing.expectEqualStrings("usage_records", recursive_delete.mutation.target_table_name);
            try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, recursive_delete.mutation.mutation.req.kind);
            try std.testing.expect(sql_adapter.recursiveJoinedMutationSourceUsesCte(recursive_delete.mutation.mutation.req, recursive_delete.recursive.cte_name));
        },
        else => return error.TestUnexpectedResult,
    }

    var merge_plan = try lowerWritePlanAlloc(
        alloc,
        "WITH RECURSIVE source_rows AS (SELECT id, status FROM usage_records UNION ALL SELECT child.id, child.status FROM usage_records AS child JOIN source_rows AS parent ON child.organization_id = parent.id) MERGE INTO usage_records USING source_rows ON usage_records.id = source_rows.id WHEN MATCHED THEN UPDATE SET status = source_rows.status",
        schema,
        &.{},
        .{},
    );
    defer merge_plan.deinit(alloc);
    switch (merge_plan) {
        .recursive_merge_mutation => |recursive_merge| {
            try std.testing.expectEqualStrings("source_rows", recursive_merge.recursive.cte_name);
            try std.testing.expectEqualStrings("usage_records", recursive_merge.merge.target_table_name);
            try std.testing.expectEqualStrings("source_rows", recursive_merge.merge.source.source_cte);
            try std.testing.expectEqual(@as(usize, 0), recursive_merge.merge.ctes.len);
            try std.testing.expectEqual(@as(usize, 1), recursive_merge.merge.matched_arms.len);
            try std.testing.expectEqual(@as(usize, 1), recursive_merge.merge.matched_arms[0].update.len);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "postgres sql adapter lowers direct select set operation query plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"},"amount":{"type":"numeric"},"created_at":{"type":"datetime"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    var parsed = try schema_api.parseValidatedTableSchema(alloc, schema_json);
    defer parsed.deinit(alloc);
    const schema = try schema_api.deriveRuntimeTableSchema(alloc, parsed);
    defer runtime_schema.freeSchema(alloc, schema);

    var disjoint_union = try lowerSelectAlloc(
        alloc,
        "SELECT id FROM usage_records WHERE status = 'open' UNION ALL SELECT id FROM usage_records WHERE status = 'closed' ORDER BY id ASC LIMIT 5 OFFSET 2",
        schema,
        &.{},
    );
    defer disjoint_union.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", disjoint_union.table_name);
    try std.testing.expectEqual(@as(usize, 0), disjoint_union.ctes.len);
    try std.testing.expectEqual(@as(usize, 0), disjoint_union.query.predicates.len);
    try std.testing.expectEqual(@as(usize, 2), disjoint_union.query.or_predicates.len);
    try std.testing.expectEqualStrings("status", disjoint_union.query.or_predicates[0].predicates[0].field);
    try std.testing.expectEqualStrings("\"open\"", disjoint_union.query.or_predicates[0].predicates[0].value_json.?);
    try std.testing.expectEqualStrings("\"closed\"", disjoint_union.query.or_predicates[1].predicates[0].value_json.?);
    try std.testing.expectEqual(@as(usize, 1), disjoint_union.query.order_by.len);
    try std.testing.expectEqualStrings("id", disjoint_union.query.order_by[0].field);
    try std.testing.expectEqual(@as(u32, 5), disjoint_union.query.limit.?);
    try std.testing.expectEqual(@as(u32, 2), disjoint_union.query.offset);

